
const KEY='save-cash-v2';const TODAY=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());let d=CashModel.migrate();let ready=false;let scratchCounter=0;const scratchStates={};let testValue=0;

function storageError(e){document.getElementById('storage-state').textContent='Не удалось сохранить: '+e.message+' · экспортируйте JSON';}
const fmt=n=>Number(n||0).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₪';const sum=CashModel.total;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=()=>crypto.randomUUID();const cibus=()=>CashModel.cibus(d).amount;const child=()=>CashModel.child(d);const totalSub=()=>sum(d.subs.filter(x=>x.active!==false&&!x.deleted));const purchasesCash=()=>sum(CashModel.unique(d.purchases).filter(x=>CashModel.method(x.method)==='debit'&&CashModel.inPeriod(d,x.date)));const purchasesCard=()=>sum(CashModel.unique(d.purchases).filter(x=>CashModel.method(x.method)==='credit'&&CashModel.inPeriod(d,x.date)));const planned=()=>sum(d.planned.filter(x=>!x.deleted));const holiday=()=>sum(d.holidays.filter(x=>!x.deleted));const expenses=()=>CashModel.calculate(d).expenses;const forecast=()=>CashModel.calculate(d).forecast;const free=()=>CashModel.calculate(d).free;const item=(label,value,color='')=>`<div class="row"><span>${label}</span><span class="money ${color}">${fmt(value)}</span></div>`;
const PANEL_GROUPS={cibus:'cibus',child:'child',subs:'payments',installments:'payments',holidays:'plans',planned:'plans',purchases:'purchases',forecast:'payments',chart:'analysis',bankrecon:'payments',reconciliation:'analysis'};
let currentView='home';let viewExpanded={};
function expanded(key){return currentView==='home'?!!d.open[key]:(viewExpanded[key]??true)}
function section(key,title,content,total=''){return `<section class="card app-panel" data-panel="${PANEL_GROUPS[key]}" data-section="${key}"><div class="section-head" onclick="toggle('${key}')"><h2>${title}</h2><div><b>${total}</b> <span data-caret>${expanded(key)?'⌃':'⌄'}</span></div></div><div class="section-body" ${expanded(key)?'':'hidden'}>${content}</div></section>`}
function navigationHTML(){return `<nav class="budget-navigation" aria-label="Разделы бюджета"><button class="back-home" id="backHome" onclick="goView('home')" hidden>← Назад</button><div class="budget-tabs" id="budgetTabs">${[['purchases','Покупки','cart'],['payments','Платежи','card'],['child',d.childName==='ребёнок'?'Максим':d.childName||'Максим','family'],['cibus','Cibus','meal'],['plans','Планы','calendar'],['analysis','Расчёты','chart'],['all','Все блоки','blocks']].map(([key,label,icon])=>`<button class="budget-tab" data-view="${key}" aria-pressed="false" onclick="goView('${key}')">${navigationIcon(icon)}<span>${esc(label)}</span></button>`).join('')}</div></nav>`}
function navigationIcon(name){const paths={cart:'<path d="M3 3h2l3 12h10l3-9H6M9 20h.01M18 20h.01"/>',card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20M6 15h4"/>',family:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3m2-15a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v1"/>',meal:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v18M17 3c-3 4-3 8 1 9v9m0-18v9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18m-13 5h.01m4 0h.01m4 0h.01"/>',chart:'<path d="M3 3v18h18M7 16v-4m5 4V8m5 8V5"/>',blocks:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>'};return '<svg class="ui-svg" viewBox="0 0 24 24" aria-hidden="true">'+paths[name]+'</svg>'}
function goView(key){if(!['home','all','purchases','payments','child','cibus','plans','analysis'].includes(key))return;currentView=key;viewExpanded={};applyNavigation();window.scrollTo({top:0,behavior:'instant'})}
function applyNavigation(){const root=document.getElementById('app');root.querySelectorAll('[data-panel]').forEach(panel=>{const group=panel.dataset.panel;panel.hidden=currentView!=='all'&&group!==currentView});document.getElementById('budgetTabs').hidden=currentView==='all';document.getElementById('backHome').hidden=currentView==='home';root.querySelectorAll('[data-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===currentView)));root.querySelectorAll('[data-section]').forEach(panel=>{const open=expanded(panel.dataset.section);panel.querySelector('.section-body').hidden=!open;panel.querySelector('[data-caret]').textContent=open?'⌃':'⌄'})}

function legacyEditable(key,label){return `<div class="row"><span>${label}</span><div class="field" id="field-${key}"><b class="money display">${fmt(d[key])}</b><input class="edit" type="number" step="0.01" value="${d[key]}" onblur="commit('${key}',this.value)" onkeydown="if(event.key==='Enter')this.blur()"><button class="icon" title="Изменить" onclick="edit('${key}')">✎</button></div></div>`}
function legacyEditableItem(collection,x){return `<div class="row"><span>${esc(x.name)}${collection==='subs'?`<div class="small">Ориентировочно ${esc(x.day||'—')}-е числа</div><label class="small check-line"><input type="checkbox" ${x.included_in_statement?'checked':''} onchange="included('${x.id}',this.checked)"> В выписке</label>`:''}${x.date?`<div class="small">${esc(x.date)} · ${esc(x.type||'Запланировано')}</div>`:''}</span><div class="field" id="item-${x.id}"><b class="money display">${fmt(x.amount)}</b><input class="edit" type="number" step="0.01" value="${x.amount}" onblur="commitItem('${collection}','${x.id}',this.value)" onkeydown="if(event.key==='Enter')this.blur()"><button class="icon" onclick="editItem('${x.id}')">✎</button>${['planned','holidays'].includes(collection)?`<button class="icon" title="Изменить название и дату" onclick="editRecord('${collection}','${x.id}')">⋯</button>`:''}<button class="icon danger" onclick="removeItem('${collection}','${x.id}')">×</button></div></div>`}
function scratch(){const key='salary-'+scratchCounter++;const stage=scratchStates[key]||0;return `<span class="salary-group"><button class="scratch stage${stage}" aria-label="Защитное покрытие зарплаты" onclick="scratchTap('${key}')"><span class="salary-value">${stage===3?fmt(d.salary):stage?'<span aria-hidden="true">'+fmt(d.salary)+'</span>':'••••••'}</span><span class="coating"></span></button><button class="icon pencil" title="Изменить зарплату" aria-label="Изменить зарплату" onclick="salaryEditTap('${key}')">✎</button></span>`}
function render(){pay='Ашрай';scratchCounter=0;const spent=expenses();const progress=Math.max(0,Math.min(100,100*(Number(d.balance)+Number(d.salary)-spent-Number(d.limit))/Math.max(1,Number(d.salary))));document.getElementById('app').innerHTML=`${!d.initialized?welcomeHTML():''}${navigationHTML()}
<section class="card app-panel" data-panel="home"><div class="top-summary"><h2>▣ Цель экономии — ${monthName()}</h2><span class="chip">${esc(d.statementStatus)}</span></div><div class="sub">${periodLabel()} · Цель: баланс не ниже ${fmt(d.limit)} <button class="icon" onclick="editMoneyKey('limit','Целевой баланс')" aria-label="Изменить целевой баланс">✎</button></div><div class="grid" style="margin-top:17px"><div><div class="sub">Текущий баланс банка</div><div class="bank-top-value"><b class="big">${fmt(d.balance)}</b><button class="icon" onclick="editBankBalance()" aria-label="Изменить баланс банка">✎</button></div></div><div><div class="sub">Аренда + ${d.loanActive?'платёж по кредиту':'кредит отсутствует'}</div><div class="big">${fmt(Number(d.rent)+(d.loanActive?Number(d.loan):0))}</div></div><div><div class="sub">Зарплата · ${prettyDate(d.salaryDate)}</div><div style="margin-top:7px">${scratch()}</div></div><div><div class="sub">Расчётный запас до цели</div><div class="big ${free()>=0?'green':'red'}">${fmt(free())}</div></div></div>${debtScaleHTML()}<div class="row small"><span>Новые покупки: ${fmt(purchasesCash()+purchasesCard())}</span><span class="green">Запас: ${fmt(free())}</span></div><div class="line"></div>${item('Прогноз после всех резервов',forecast(),forecast()>=0?'green':'red')}${item('Целевой предел минуса',d.limit)}<div class="note">Это расчёт по известным статьям, а не подтверждённая доступная сумма. Состав полного credit требует сверки. Спорные статьи отмечаются отдельно.</div></section>
<section class="card app-panel" data-panel="analysis"><div class="top-summary"><h2>⚙ Цель экономии</h2><button class="icon" onclick="showSettings()">☷</button></div><div class="sub">Расчётный период ${periodLabel()}</div><div class="row"><span>Ожидаемая зарплата</span><div class="field">${scratch()}</div></div></section>
${section('cibus','♜ Cibus',`${numeric('cibusDays','Рабочих дней за период')}${numeric('cibus50','Ваучеры по 50 ₪ · дней')}${numeric('cibusOrdinary','Обычные обеды · дней')}${editable('cibusLunchShare','Личное участие за обед')}${cibusExtrasHTML()}<div class="line"></div>${item('40 ₪: '+CashModel.cibus(d).n40+' × 2 ₪',CashModel.cibus(d).n40*2)}${item('50 ₪: '+CashModel.cibus(d).n50+' × 12 ₪',CashModel.cibus(d).n50*12)}${item((d.cibusActual.length?'Обеды · фактические и плановые':'Обеды: '+CashModel.cibus(d).ordinary+' × '+fmt(d.cibusLunchShare)),(CashModel.cibus(d).amount-CashModel.cibus(d).n40*2-CashModel.cibus(d).n50*12))}<div class="gray">${item('Моё участие Cibus',cibus())}</div><label class="small"><input type="checkbox" ${d.cibusIncluded?'checked':''} onchange="d.cibusIncluded=this.checked;save();render()"> Уже входит в сумму выписки</label>`,fmt(cibus()))}
${section('child','♧ Алименты и '+esc(d.childName||'ребёнок'),childHTML(),fmt(child()))}
${section('subs','↻ Ежемесячные абонплаты',`<details class="help"><summary>Как работает «В выписке»?</summary>Отмечено — платёж уже внутри общей суммы credit, отдельно не вычитается. Без отметки — добавляется к расходам сверх выписки. Приход денег не создаётся.</details>${d.subs.filter(x=>!x.deleted).map(x=>editableItem('subs',x)).join('')}<button class="compact" onclick="editRecurring()">＋ Добавить абонплату</button><div class="line"></div>${item('Всего абонплат',totalSub())}`,fmt(totalSub()))}
${section('installments','▤ Рассрочки и будущие списания',installmentsHTML(),fmt(sum(d.installments.filter(x=>x.active&&!x.deleted&&x.status==='Подтверждено').map(x=>({amount:x.amount_per_payment})))))}
${section('holidays','🎁 Праздничные покупки',`${d.holidays.filter(x=>!x.deleted).map(x=>editableItem('holidays',x)).join('')}<button class="compact" onclick="addItem('holidays')">＋ Добавить праздник</button><div class="line"></div>${item('Всего запланировано',holiday())}`,fmt(holiday()))}
${section('planned','◷ Запланированные покупки',`${d.planned.filter(x=>!x.deleted).map(x=>editableItem('planned',x)).join('')}<button class="compact" onclick="addItem('planned')">＋ Запланировать покупку</button><div class="line"></div>${item('Всего запланировано',planned())}`,fmt(planned()))}
${section('purchases','🛒 Журнал новых покупок',`<div class="form-row"><label>Что куплено / магазин</label><div class="field"><input id="shop" style="flex:1;width:100%" placeholder="Покупка или магазин" oninput="suggest(this.value)"><button class="photo-button" onclick="selectReceipt(false)" title="Галерея" aria-label="Галерея">${uiIcon('gallery')}</button><button class="photo-button" onclick="selectReceipt(true)" title="Камера" aria-label="Камера">${uiIcon('camera')}</button><input id="receiptFile" type="file" accept="image/*" hidden onchange="attachReceipt(this.files[0])"></div><div id="receiptNotice" class="small"></div><div id="ocrDraftContainer">${receiptDraftHTML()}</div><div id="suggestions" class="suggestions"></div></div><div class="two"><div class="form-row"><label>Сумма, ₪</label><input id="amount" type="number" step="0.01" placeholder="0,00"></div><div class="form-row"><label>Дата покупки</label><input id="date" type="date" value="${TODAY()}"></div></div><div class="form-row"><label>Категория</label><button id="categoryChoice" class="compact" onclick="categoryTap()">Выбери категорию</button><select id="category" hidden onchange="categorySelected()"><option value="">Выбери категорию</option>${['Продукты','Рестораны','Развлечения','Дети','Дом','Одежда','Транспорт','Ненужные покупки','Здоровье','Другое'].map(x=>`<option>${x}</option>`).join('')}</select><input id="customCategory" hidden style="margin-top:6px" placeholder="Или введи свою категорию"></div><div class="form-row"><label>Способ оплаты</label><div class="actions"><button id="pay-card" class="primary compact" onclick="choosePay('Ашрай')">credit</button><button id="pay-cash" class="compact" onclick="choosePay('Счёт')">debit</button></div></div><div class="form-row"><label>Статус</label>${statusPicker('status','Совершено',true)}</div><button class="primary" style="width:100%" onclick="addPurchase()">＋ Добавить покупку</button><div class="line"></div><div class="row"><b>Покупки</b><button class="compact" onclick="toggle('report')">${d.open.report?'Свернуть':'Открыть лог-отчёт'}</button></div>${d.open.report?'<div class="report-scroll">'+reportHTML()+'</div>':''}`,fmt(purchasesCash()+purchasesCard()))}
<section class="card app-panel" data-panel="payments">${editable('reserve','Резерв банковских рисков')}${editable('limit','Целевой предел минуса')}</section>
${section('bankrecon','⇄ Сверка Ашрай',bankReconciliationHTML())}
${section('forecast','▣ Итоговый прогноз',`${editable('balance','Остаток на счёте · исходный')}<div class="row"><span>Ожидаемая зарплата</span><div class="field">${scratch()}</div></div>${item('credit октября · уже в исходном балансе',d.ashrai)}<div class="small">Повторно не вычитается. Ноябрьская сумма частичная; проверьте полноту выписки.</div>${editable('statementTotal','credit периода · сумма выписки')}<div class="row"><span class="small">Статус выписки</span><button class="compact" onclick="changeStatementStatus()">${esc(d.statementStatus)} ✎</button></div>${dateField('statementDate','Дата списания credit')}<div class="gray obligation">${d.loanActive?editable('loan','Платёж по кредиту'):''}<button class="compact" onclick="set('loanActive',${!d.loanActive})">${d.loanActive?'− Убрать кредит':'＋ Вернуть платёж по кредиту'}</button>${dateField('loanDate','Дата списания кредита')}</div>
<div class="gray obligation">${editable('rent','Аренда')}${dateField('rentDate','Дата списания аренды')}</div>${item('Алименты и ребёнок',-child())}${item('Cibus',-cibus())}${item('Абонплаты · детализация',-totalSub())}<div class="small">Статьи с отметкой «в выписке» повторно не вычитаются. Итог по постатейной сверке ниже.</div>${item('Праздники и покупки',-holiday())}${item('Запланированные',-planned())}${item('Новые покупки · credit',-purchasesCard())}${item('Новые покупки · debit',-purchasesCash())}${item('Резерв',-d.reserve)}<div class="line"></div>${item('Прогноз после расходов',forecast(),forecast()>=0?'green':'red')}${item('Баланс при использовании целевого лимита',d.limit)}<div class="gray">${item('Запас до целевого предела',free(),free()>=0?'green':'red')}</div><div class="small">Расчётная версия. Полноту выписки и спорные статьи необходимо сверить. Подписки и Cibus — прогноз сверх выписки, пока не отмечены включёнными.</div>`,fmt(forecast()))}

<section class="card app-panel" data-panel="analysis"><h2>▣ Цель экономии — ${monthName()}</h2>${item('Лимит новых покупок · расчётная версия',free()+purchasesCash()+purchasesCard())}${item('Уже потрачено',purchasesCash()+purchasesCard())}${item('Осталось потратить · до сверки',free())}<div class="line"></div>${calculatorHTML()}<div class="line"></div><div class="grid"><div><div class="sub">Ожидаемая зарплата</div>${scratch()}</div><div><div class="sub">Всего расходов и резервов</div><div class="big">${fmt(expenses())}</div></div><div><div class="sub">Прогнозный остаток</div><div class="big">${fmt(forecast())}</div></div><div><div class="sub">Запас относительно цели</div><div class="big ${free()>=0?'green':'red'}">${fmt(free())}</div></div></div>${debtScaleHTML()}</section>${section('chart','↗ График credit и экономия',chartHTML())}${section('reconciliation','≡ Постатейная сверка',reconciliationHTML())}<div id="storage-state" class="small"></div><div class="small" style="text-align:center">Save Cash · v3.0 RC1 · данные на этом устройстве</div>`;applyNavigation()}
function categoryReportHTML(){let cats={};for(let x of CashModel.unique(d.purchases).filter(x=>CashModel.inPeriod(d,x.date))){(cats[x.category||'Другое']??=[]).push(x)}return `<div class="actions"><button class="compact" onclick="document.querySelectorAll('.cat').forEach(x=>x.open=true)">Развернуть все</button><button class="compact" onclick="document.querySelectorAll('.cat').forEach(x=>x.open=false)">Свернуть все</button></div><div class="gray">${item('Обязательные платежи',Number(d.rent)+(d.loanActive?Number(d.loan):0))}${item('Алименты и ребёнок',child())}${item('Абонплаты',totalSub())}</div>${Object.entries(cats).map(([name,items])=>`<details class="cat"><summary><b>${esc(name)} · ${fmt(sum(items))}</b></summary>${items.map(x=>`<div class="purchase row"><span>${esc(x.name)}<div class="small">${esc(x.date)} · ${esc(methodLabel(x.method))} · ${esc(x.status)}</div>${x.document_id||x.attachment?`<button class="compact" onclick="viewReceipt('${x.id}')">Чек</button>`:''}${x.receipt_items?.length?`<details class="small"><summary>Товары (${x.receipt_items.length})</summary>${x.receipt_items.map(v=>`<div class="receipt-item"><span dir="auto">${esc(v.name)}</span><span>${fmt(v.amount)}</span></div>`).join('')}</details>`:''}</span><div class="field"><b>${fmt(x.amount)}</b><button class="icon" onclick="editPurchase('${x.id}')">✎</button><button class="icon danger" onclick="removeItem('purchases','${x.id}')">×</button></div></div>`).join('')}</details>`).join('')||'<div class="empty">Покупок пока нет</div>'}`}
function toggle(k){if(PANEL_GROUPS[k]&&currentView!=='home')viewExpanded[k]=!expanded(k);else d.open[k]=!d.open[k];save();render()}function set(k,v){d[k]=typeof d[k]==='boolean'?Boolean(v):Number(v)||0;save();render()}function edit(k){const e=document.getElementById('field-'+k);if(!e)return;e.classList.add('editing');e.querySelector('input')?.focus()}function commit(k,v){const n=Number(v);if(!Number.isFinite(n)||(!['limit','balance'].includes(k)&&n<0)){render();return}d[k]=n;if(k.startsWith('cibus')){const c=CashModel.cibus(d);d.cibusDays=c.days;d.cibus50=c.n50;d.cibusOrdinary=c.ordinary;}save();render()}function editItem(id){const e=document.getElementById('item-'+id);e.classList.add('editing');e.querySelector('input').focus()}function commitItem(c,id,v){if(!Number.isFinite(Number(v))||Number(v)<0){render();return}let x=d[c].find(x=>x.id===id);if(x)x.amount=Number(v)||0;save();render()}function addItem(c){const names={extra:'Дополнительный расход',subs:'Абонплата',holidays:'Праздничная покупка',planned:'Запланированная покупка'};let opts=c==='holidays'?`<select id="modalType"><option>День рождения</option><option>Новый год</option><option>Особая дата</option><option>Другое</option></select>`:'';modal(`<h3>${names[c]}</h3>${opts}<div class="form-row"><label>Название</label><input id="modalName" placeholder="Название" style="width:100%"></div><div class="form-row"><label>Сумма, ₪</label><input id="modalAmount" type="number" value="0" style="width:100%"></div>${['planned','holidays'].includes(c)?`<div class="form-row"><label>Дата</label><input type="date" id="modalDate" value="${TODAY()}"></div>`:''}<div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveItem('${c}')">Добавить</button></div>`)}function saveItem(c){if(!(Number(document.getElementById('modalAmount').value)>=0)||!Number.isFinite(Number(document.getElementById('modalAmount').value)))return;const name=document.getElementById('modalName').value.trim()||document.getElementById('modalType')?.value||'Без названия';d[c].push({id:id(),name,amount:Number(document.getElementById('modalAmount').value)||0,date:document.getElementById('modalDate')?.value,type:document.getElementById('modalType')?.value,source:'Ручной ввод',included_in_statement:false});save();closeModal();render()}function modal(html){document.getElementById('overlay').innerHTML=`<div class="modal-cover" onclick="if(event.target===this)closeModal()"><div class="modal">${html}</div></div>`}function closeModal(){document.getElementById('overlay').innerHTML=''}function confirmSmall(title,yes){window._confirm=yes;modal(`<h3>${title}</h3><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="closeModal();window._confirm()">Подтвердить</button></div>`)}let pay='Ашрай';function choosePay(v){if(v==='Счёт'){confirmSmall('Подтвердить оплату со счёта?',()=>{pay=v;document.getElementById('pay-cash').classList.add('primary');document.getElementById('pay-card').classList.remove('primary')})}else{pay=v;document.getElementById('pay-card').classList.add('primary');document.getElementById('pay-cash').classList.remove('primary')}}const shops=['Шуферсаль','Shufersal','Tiv Taam','Тив Таам','TIFF','Super-Pharm','Супер-Фарм','Rami Levy','Рами Леви','Victory','Виктори','Yochananof','Йохананоф','AM:PM','Арома','Aroma','Макдональдс','McDonald’s','KSP','IKEA','Икеа','Fox','H&M','ZARA','BESTEC','Gold Love'];function suggest(v){let q=v.toLowerCase().trim();document.getElementById('suggestions').innerHTML=q?shops.filter(x=>x.toLowerCase().includes(q)||q==='тив'&&x==='Tiv Taam').slice(0,5).map(x=>`<button onclick="document.getElementById('shop').value='${x}';suggest('')">${x}</button>`).join(''):''}function scratchTap(key){scratchStates[key]=((scratchStates[key]||0)+1)%4;render()}const editTaps={};function salaryEditTap(key){const now=Date.now();if(!editTaps[key]||now-editTaps[key]>1800){editTaps[key]=now;return}editTaps[key]=0;confirmSmall('Открыть редактирование зарплаты?',()=>modal(`<h3>Изменить ожидаемую зарплату</h3><input id="newSalary" type="number" style="width:100%" value="${d.salary}"><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveSalary()">Сохранить</button></div>`))}function testImpact(){let v=Math.max(0,Number(document.getElementById('testCost').value)||0);testValue=v;document.getElementById('impact').innerHTML=`Запас после покупки: <b class="${free()-v>=0?'green':'red'}">${fmt(free()-v)}</b><div class="small">Изменение прогноза: −${fmt(v)}</div>`}
function prettyDate(value){return new Date(value+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}
function monthName(){return new Date(d.periodEnd+'T12:00:00').toLocaleDateString('ru-RU',{month:'long'})}
function periodLabel(){return [d.periodStart,d.periodEnd].map(x=>x.split('-').reverse().join('.')).join('–')}
function numeric(key,label){return editable(key,label).replace(fmt(d[key])+'</b>',String(d[key])+'</b>')}
function dateField(key,label){return `<div class="row"><span>${label}</span><span class="field"><b class="small">${esc(d[key])}</b><button class="icon" onclick="editDate('${key}')">✎</button></span></div>`}
function editDate(key){modal(`<h3>Изменить дату</h3><input type="date" id="newDate" value="${esc(d[key])}"><div class="actions"><button onclick="closeModal()">Отмена</button><button onclick="saveDate('${key}')">Сохранить</button></div>`)}
function saveDate(key){const date=document.getElementById('newDate').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return;if(key==='periodStart'&&date>=d.periodEnd||key==='periodEnd'&&date<=d.periodStart)return;d[key]=date;save();closeModal();render()}
function included(key,value){d.subs.find(x=>x.id===key).included_in_statement=value;save();render()}

function setInstallment(key,field,value){d.installments.find(x=>x.id===key)[field]=value;save();render()}





function togglePeriod(key){d.selectedPeriods=d.selectedPeriods.includes(key)?d.selectedPeriods.filter(x=>x!==key):[...d.selectedPeriods,key];save();render()}
function carryExcess(){confirmSmall('Сохранить перенос для следующего периода?',()=>{d.nextPeriodCarry=CashModel.saving(d).excess;save();modal(`<h3>Перенос сохранён</h3><p>При открытии следующего периода требуемая экономия увеличится на ${fmt(d.nextPeriodCarry)}.</p><button onclick="closeModal()">Закрыть</button>`)})}
function download(name,type,contents){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function exportLedger(){const rows=CashModel.calculate(d).rows;const cells=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('Save-Cash-reconciliation.csv','text/csv;charset=utf-8','\ufeff'+[['Статья','Сумма ₪','Источник','Инструмент','Дата операции','Дата списания','Учтена / вне периода','Статус'],...rows.map(x=>[x.name,x.amount,x.source,x.method,x.operation_date,x.date,x.included?'Да':'Нет',x.status])].map(r=>r.map(cells).join(';')).join('\r\n'))}






let swRegistration;let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});async function installApp(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else modal('<h3>Установка на Android</h3><p>Откройте опубликованную HTTPS-ссылку в Chrome → ⋮ → «Установить приложение» или «Добавить на главный экран».</p><button onclick="closeModal()">Закрыть</button>')}


let categoryClicks=0;
function categoryTap(){const select=document.getElementById('category'),custom=document.getElementById('customCategory');categoryClicks++;if(categoryClicks===1){select.hidden=false;custom.hidden=true;select.focus()}else{select.hidden=true;custom.hidden=false;custom.focus();categoryClicks=0}}
function categorySelected(){const select=document.getElementById('category');document.getElementById('categoryChoice').textContent=select.value||'Выбери категорию';select.hidden=true;categoryClicks=0}
document.addEventListener?.('click',e=>{if(!['category','categoryChoice','customCategory'].includes(e.target.id)){const select=document.getElementById('category');if(select)select.hidden=true;const custom=document.getElementById('customCategory');if(custom)custom.hidden=true;categoryClicks=0}});
function saveSalary(){const n=Number(document.getElementById('newSalary').value);if(!Number.isFinite(n)||n<0)return;d.salary=n;Object.keys(scratchStates).forEach(k=>scratchStates[k]=0);save();closeModal();render()}
function changeStatementStatus(){modal(`<h3>Статус выписки</h3><div class="stack">${['Частичная выписка','Полная выписка · сверена'].map(status=>`<button onclick="setStatementStatus('${status}')">${status}</button>`).join('')}<button onclick="closeModal()">Отмена</button></div><p class="small">При полной выписке отметьте входящие в неё подписки, рассрочки, Cibus и покупки.</p>`)}
async function checkUpdate(){try{if(!swRegistration){modal('<h3>Обновление пока недоступно</h3><p>Нужно открыть приложение по HTTPS и дождаться регистрации офлайн-режима.</p><button onclick="closeModal()">Закрыть</button>');return}await swRegistration.update();if(swRegistration.waiting)confirmSmall('Обновить приложение? Сначала сохраним данные.',async()=>{await Storage.flush();swRegistration.waiting.postMessage('ACTIVATE_UPDATE');window.location.reload()});else modal('<h3>Проверка завершена</h3><p>Если обновление загружается, оно применится при следующем открытии приложения.</p><button onclick="closeModal()">Закрыть</button>')}catch(e){modal('<h3>Не удалось проверить обновление</h3><p>'+esc(e.message)+'</p><button onclick="closeModal()">Закрыть</button>')}}
function setStatementStatus(status){d.statementStatus=status;save();closeModal();render()}
function welcomeHTML(){return '<section class="card welcome"><h2>Добро пожаловать в Save Cash</h2><p class="small">Загрузите свою резервную копию JSON. Данные сохраняются только на этом устройстве и не отправляются на GitHub.</p><label class="compact">Загрузить JSON <input type="file" accept=".json,application/json" onchange="importData(this.files[0])"></label><div class="actions"><button class="compact" onclick="d.initialized=true;save();render()">Начать с пустого бюджета</button></div></section>'}
let draftAttachment=null;
function selectReceipt(camera){const input=document.getElementById('receiptFile');if(camera)input.setAttribute('capture','environment');else input.removeAttribute('capture');input.click()}


function editRecord(collection,key){const x=d[collection].find(x=>x.id===key);modal(`<h3>Изменить запись</h3><div class="form-row"><label>Название</label><input id="recordName" value="${esc(x.name)}"></div><div class="form-row"><label>Дата</label><input id="recordDate" type="date" value="${esc(x.date||TODAY())}"></div><div class="actions"><button onclick="closeModal()">Отмена</button><button onclick="saveRecord('${collection}','${key}')">Сохранить</button>${collection==='planned'?`<button onclick="payPlanned('${key}')">Покупка совершена</button>`:''}</div>`)}
function saveRecord(collection,key){const x=d[collection].find(x=>x.id===key);x.name=document.getElementById('recordName').value.trim()||x.name;x.date=document.getElementById('recordDate').value||x.date;save();closeModal();render()}
function payPlanned(key){const x=d.planned.find(x=>x.id===key);if(x.transaction_id)return;const transaction={...x,id:id(),category:'Другое',method:'Ашрай',status:'Совершено',source:'Из плана'};x.transaction_id=transaction.id;d.purchases.push(transaction);save();closeModal();render()}
function legacyEditPurchase(key){const x=d.purchases.find(x=>x.id===key);modal(`<h3>Покупка</h3><div class="form-row"><label>Название</label><input id="editName" value="${esc(x.name)}"></div><div class="form-row"><label>Сумма</label><input id="editAmount" type="number" value="${x.amount}" step=".01" min="0"></div><div class="form-row"><label>Дата покупки</label><input id="editDate" type="date" value="${esc(x.date)}"></div><div class="form-row"><label>Дата списания</label><input id="editCharge" type="date" value="${esc(CashModel.chargeDate(x,d))}"></div><div class="form-row"><label>Статус</label>${statusPicker('editStatus',x.status,false)}</div><div class="form-row"><label>Связь с рассрочкой, подпиской или уроками</label><select id="editLink"><option value="">Нет</option>${d.installments.map(i=>`<option value="${i.id}" ${x.installment_id===i.id?'selected':''}>${esc(i.merchant)}</option>`).join('')}${d.subs.map(i=>`<option value="${i.id}" ${x.recurring_id===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}${CashModel.lessonPayments(d).map(p=>`<option value="lesson:${p.id}" ${x.lesson_payment_id===p.id?'selected':''}>${esc(p.name)} · ${esc(p.charge_date)} · ${fmt(p.amount)}</option>`).join('')}</select></div><div class="actions"><button onclick="closeModal()">Отмена</button><button onclick="savePurchase('${key}')">Сохранить</button></div>`)}
function legacySavePurchase(key){const x=d.purchases.find(x=>x.id===key),amount=Number(document.getElementById('editAmount').value);if(!Number.isFinite(amount)||amount<=0)return;Object.assign(x,{name:document.getElementById('editName').value.trim()||x.name,amount,date:document.getElementById('editDate').value,charge_date:document.getElementById('editCharge').value,status:document.getElementById('editStatus').value,installment_id:document.getElementById('editLink').value.startsWith('sub-')?'':document.getElementById('editLink').value,recurring_id:document.getElementById('editLink').value.startsWith('sub-')?document.getElementById('editLink').value:''});if(document.getElementById('editLink').value.startsWith('lesson:')){x.lesson_payment_id=document.getElementById('editLink').value.slice(7);x.installment_id='';x.recurring_id=''}else delete x.lesson_payment_id;x.included_in_statement=CashModel.method(x.method)==='credit'&&['Включено в выписку','Списано со счёта'].includes(x.status);save();closeModal();render()}

function uiIcon(name){const paths={gallery:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 16 5-5 4 4 3-3 6 6"/>',camera:'<path d="M8 6 9.5 3h5L16 6h4a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2Z"/><circle cx="12" cy="13" r="4"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 8M20 2v5h-5"/>',export:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18"/>',sliders:'<path d="M4 7h7m4 0h5M4 17h3m4 0h9"/><circle cx="13" cy="7" r="2"/><circle cx="9" cy="17" r="2"/>'};return '<svg class="ui-svg" viewBox="0 0 24 24" aria-hidden="true">'+(paths[name]||paths.sliders)+'</svg>'}
function statusPicker(key,current,planned){const values=['Совершено',...(planned?['Запланировано']:[]),'Включено в выписку','Списано со счёта'];return `<input type="hidden" id="${key}" value="${esc(current)}"><details class="status-picker" id="picker-${key}"><summary><span id="label-${key}">${esc(current)}</span><span>⌄</span></summary><div class="status-options">${values.map((v,i)=>`<button type="button" class="${v===current?'selected':''}" onclick="selectStatus('${key}',${i},${!!planned})">${v}</button>`).join('')}</div></details>`}
function selectStatus(key,index,planned){const values=['Совершено',...(planned?['Запланировано']:[]),'Включено в выписку','Списано со счёта'];document.getElementById(key).value=values[index];document.getElementById('label-'+key).textContent=values[index];const picker=document.getElementById('picker-'+key);picker.open=false;picker.querySelectorAll('button').forEach((b,i)=>b.classList.toggle('selected',i===index))}


let lessonDraft;




function addLessonPayment(){syncLessonDraft();lessonDraft.payments.push({id:id(),amount:Math.max(0,lessonDraft.total-sum(lessonDraft.payments)),charge_date:d.statementDate,method:'Ашрай',included_in_statement:false});lessonEditor()}
function removeLessonPayment(i){syncLessonDraft();lessonDraft.payments.splice(i,1);lessonEditor()}


async function importLessonUpdate(raw){if(raw.app!=='Save Cash'||raw.version!==1)throw Error('Неизвестный формат обновления');validateLessons(raw.lessonBills);const bills=structuredClone(d.lessonBills);for(const b of raw.lessonBills){const i=bills.findIndex(x=>x.id===b.id);if(i>=0)bills[i]=b;else bills.push(b)}validateLessons(bills);confirmSmall('Добавить счета за уроки? Покупки, баланс и остальные данные сохранятся.',async()=>{await Storage.flush();await Storage.backup('before-lesson-update',d);d.lessonBills=bills;if(typeof raw.childName==='string')d.childName=raw.childName;if(typeof raw.lessonRecipient==='string')d.lessonRecipient=raw.lessonRecipient.slice(0,80);save();closeModal();render()})}
function calculationRows(){if(!Array.isArray(d.calculations)||!d.calculations.length)d.calculations=[{id:id(),terms:[0]}];return d.calculations}
function calcTotal(){return calculationRows().reduce((s,r)=>s+r.terms.reduce((a,n)=>a+CashModel.cents(n),0),0)/100}
function calculatorHTML(){const total=calcTotal();return `<div class="calculator"><h3>Проверка покупки + калькулятор</h3><div class="small">Нажмите на число: откроется цифровая панель. «＋» добавляет слагаемое или ещё один расчёт.</div>${calculationRows().map((r,i)=>`<div class="calc-row"><div class="calc-expression">${r.terms.map((n,j)=>`${j?'<span class="small">+</span>':''}<button class="calc-number" onclick="openKeypad(${i},${j})" aria-label="Расчёт ${i+1}, число ${j+1}">${fmt(n).replace(' ₪','')}</button>`).join('')}<button class="calc-add" onclick="appendTerm(${i})" aria-label="Добавить число в расчёт ${i+1}">＋</button></div><div class="calc-result"><span>= ${fmt(r.terms.reduce((a,n)=>a+CashModel.cents(n),0)/100)}</span>${calculationRows().length>1?`<button onclick="removeCalculation(${i})">Убрать</button>`:''}</div></div>`).join('')}<button class="compact calc-plus" onclick="addCalculation()">＋ Ещё расчёт</button><div class="gray calc-impact">Итого проверяем: <b>${fmt(total)}</b><br>Запас после покупки: <strong class="${free()-total>=0?'green':'red'}">${fmt(free()-total)}</strong></div><div class="small">Это примерка расходов. В журнал покупки не записываются.</div></div>`}
function addCalculation(){calculationRows().push({id:id(),terms:[0]});save();render()}
function removeCalculation(i){calculationRows().splice(i,1);save();render()}
function appendTerm(i){calculationRows()[i].terms.push(0);openKeypad(i,calculationRows()[i].terms.length-1)}
let keypadState;
function openKeypad(row,index){keypadState={row,index,value:String(calculationRows()[row].terms[index]||0)};modal(`<h3>Число для расчёта</h3><div id="keypadValue" class="keypad-value">${esc(keypadState.value.replace('.',','))}</div><div class="keypad">${['7','8','9','⌫','4','5','6','C','1','2','3','+','0',',','00','✓'].map(v=>`<button class="${v==='✓'?'primary':''}" onclick="keypadPress('${v}')" aria-label="${v==='⌫'?'Удалить цифру':v==='✓'?'Записать число':v==='C'?'Очистить число':v}">${v}</button>`).join('')}</div><div class="keypad-actions"><button class="compact" onclick="closeModal();render()">Отмена</button><button class="compact" onclick="keypadPress('✓')">Записать</button></div>`)}
function keypadPress(key){const k=keypadState;if(key==='✓'||key==='+'){const n=Number(k.value);if(!Number.isFinite(n)||n<0)return;calculationRows()[k.row].terms[k.index]=n;save();if(key==='+'){calculationRows()[k.row].terms.push(0);openKeypad(k.row,calculationRows()[k.row].terms.length-1)}else{closeModal();render()}return}if(key==='C')k.value='0';else if(key==='⌫')k.value=k.value.slice(0,-1)||'0';else if(key===','){if(!k.value.includes('.'))k.value+='.'}else if(k.value.length<12&&(!k.value.includes('.')||k.value.split('.')[1].length<2)){const next=k.value==='0'?key:k.value+key;if(!next.includes('.')||next.split('.')[1].length<=2)k.value=next}document.getElementById('keypadValue').textContent=k.value.replace('.',',')}




let receiptDraft=null,ocrBusy=false,bankDraft=null,bankRunId=null,reconFocusId=null,ledgerSort={key:'name',asc:true},ledgerQuery='';
function save(action='Изменение данных'){d.schemaVersion=2;d.dataVersion=4;d.financialRevision=(d.financialRevision||0)+1;d.audit_log.push({id:id(),at:new Date().toISOString(),action});return Storage.save(d).catch(storageError)}
function validData(raw){return CashValidation.data(raw)}
function validateLessons(bills){return CashValidation.lessons(bills)}
async function start(){document.getElementById('app').innerHTML='<section class="card">Открываем ваши данные…</section>';try{const raw=await Storage.load();if(raw.dataVersion!==4)await Storage.backup('before-2026-10-16-migration',raw);d=CashModel.migrate(raw);await Storage.migrateAttachments(d);await Storage.save(d);ready=true;render()}catch(e){document.getElementById('app').innerHTML='<section class="card">Не удалось открыть хранилище. Данные не перезаписаны. '+esc(e.message)+'</section>'}}
function showSettings(){modal(`<div class="settings-head"><div><h3>Save Cash <span class="pill">v3.0 RC1</span></h3><div class="small">Бюджет до ЗП · 16.10.2026</div></div><button class="close-button" onclick="closeModal()" aria-label="Закрыть настройки">×</button></div><div class="settings-status"><span class="status-dot"></span>${swRegistration?.active?'Локальное хранилище и офлайн-режим готовы':'Подготавливаем офлайн-режим'}</div><div class="settings-group"><button class="settings-row" onclick="installApp()">${uiIcon('phone')}<span>Установить приложение</span><span>›</span></button><button class="settings-row" onclick="checkUpdate()">${uiIcon('refresh')}<span>Проверить обновление</span><span>›</span></button></div><div class="settings-label">Данные</div><div class="settings-group"><button class="settings-row" onclick="exportBackup()">${uiIcon('export')}<span>Полная резервная копия<small>ZIP: данные, оригиналы и журнал</small></span><span>›</span></button><button class="settings-row" onclick="exportData()">${uiIcon('export')}<span>Экспорт JSON<small>Данные без файлов документов</small></span><span>›</span></button><button class="settings-row" onclick="document.getElementById('restoreFile').click()">${uiIcon('folder')}<span>Восстановить ZIP / JSON</span><span>›</span></button><input id="restoreFile" type="file" accept=".zip,.json" hidden onchange="importData(this.files[0])"><button class="settings-row" onclick="showPeriodSettings()">${uiIcon('calendar')}<span>Расчётный период и даты</span><span>›</span></button><button class="settings-row" onclick="showBalanceHistory()">${uiIcon('refresh')}<span>История баланса</span><span>›</span></button><button class="settings-row" onclick="showDeleted()">${uiIcon('folder')}<span>Удалённые записи</span><span>›</span></button><button class="settings-row" onclick="showAccessInfo()">${uiIcon('sliders')}<span>Доступ и защита</span><span>›</span></button></div><div class="settings-rights">Save Cash — Бюджет до ЗП<br>© 2026 Anton Koval. All rights reserved.<br>Personal finance management application.</div><p class="small">OCR работает на устройстве. Для первой загрузки движка нужен интернет; документы не отправляются сервисам распознавания.</p>`)}
function showAccessInfo(){modal('<h3>Доступ и защита</h3><p>Финансовые данные и документы находятся только в IndexedDB этого устройства. Публичный сайт не содержит ваших сумм.</p><p>На GitHub Pages серверная авторизация новых устройств и двухчасовые приглашения недоступны. Сервер управления доступом пока не подключён. Этот выпуск не выдаёт локальное скрытие интерфейса за защиту доступа.</p><button class="compact" onclick="closeModal()">Закрыть</button>')}
function editBankBalance(){modal(`<h3>Изменить баланс банка</h3><div class="form-row"><label for="bankBalance">Сумма, ₪</label><input id="bankBalance" type="number" step=".01" value="${d.balance}"></div><div class="form-row"><label for="bankBalanceDate">Баланс актуален на дату</label><input id="bankBalanceDate" type="date" value="${esc(d.balanceDate)}"></div><p class="small">Введённый баланс должен уже включать проведённые на эту дату списания. Корректировка не создаёт доход или покупку.</p><div id="balanceError" class="red small"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveBankBalance()">Сохранить</button></div>`)}
function saveBankBalance(){try{CashModel.adjustBalance(d,Number(document.getElementById('bankBalance').value),document.getElementById('bankBalanceDate').value);save('Корректировка банковского баланса');closeModal();render()}catch(e){document.getElementById('balanceError').textContent=e.message}}
function showBalanceHistory(){modal(`<h3>История баланса</h3>${d.balanceHistory.slice().reverse().map(x=>`<div class="purchase small">${esc(x.at)}<br>${fmt(x.old)} → <b>${fmt(x.new)}</b><br>Баланс на ${esc(x.balanceDate)}</div>`).join('')||'<p class="small">Корректировок ещё нет.</p>'}<button class="compact" onclick="closeModal()">Закрыть</button>`)}
function editMoneyKey(key,label){modal(`<h3>${esc(label)}</h3><div class="form-row"><label>Сумма, ₪</label><input id="keyMoney" type="number" step=".01" value="${Number(d[key])||0}"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveMoneyKey('${key}')">Сохранить</button></div>`)}
function saveMoneyKey(key){const n=Number(document.getElementById('keyMoney').value);if(!Number.isFinite(n)||!['balance','limit'].includes(key)&&n<0)return;d[key]=n;if(key==='educationFee')d.math=n;save();closeModal();render()}
function debtScaleHTML(){const current=Math.max(0,-d.balance),projected=Math.max(0,-forecast()),max=Math.max(8000,Math.ceil(Math.max(current,projected)/1000)*1000),pct=x=>Math.min(100,Math.max(0,x/max*100));return `<div class="debt-scale"><div class="small">Задолженность: сейчас <b>${fmt(current)}</b> · прогноз <b>${fmt(projected)}</b></div><div class="debt-track" style="background:linear-gradient(to right,#b8dcca 0 ${pct(4000)}%,#f3d2a2 ${pct(4000)}% ${pct(6000)}%,#ecc1c1 ${pct(6000)}% 100%)"><i class="debt-pin current" style="left:${pct(current)}%" title="Текущий минус"></i><i class="debt-pin forecast" style="left:${pct(projected)}%" title="Прогноз минуса"></i></div><div class="debt-labels"><span>0</span><span style="left:${pct(4000)}%">4 000</span><span style="left:${pct(6000)}%">6 000</span><span>${Math.round(max).toLocaleString('ru-RU')} ₪</span></div><div class="small">Чёрная метка — сейчас · зелёная — прогноз. Положительный баланс означает отсутствие долга.</div><div class="small" style="margin-top:6px">Цель сокращения трат: ${fmt(d.savingTarget)} за период. Закрыть минус к ${esc(d.goalDate)}.</div></div>`}
function childHTML(){const off=CashModel.compensation(d),bills=d.lessonBills.filter(b=>b.subject==='hebrew'&&!b.deleted);return `<div class="gray"><h3>Алименты</h3>${editable('childSupport','Базовые алименты')}${editable('educationFee','Образование · в переводе')}${dateField('childDate','Дата перевода')}${item('Всего начислено',Number(d.childSupport)+CashModel.education(d))}</div>${lessonAccountHTML('math')}${lessonAccountHTML('hebrew')}<div class="gray"><h3>Компенсационный вычет</h3>${bills.filter(b=>CashModel.inPeriod(d,b.compensation_date)).map(b=>{const s=CashModel.lessonShares(b.total,b.shares_override);return `<div class="row"><span>${esc(b.name)}<div class="small">(доля мамы ${fmt(s.mother)}, моя ${fmt(s.father)})<br>Вычет один раз · ${esc(b.compensation_date)}</div></span><b class="money green">−${fmt(s.mother)}</b></div>`}).join('')}${!bills.length&&off?'<p class="small">Сохранён прежний вычет до заполнения счёта за уроки. Добавьте счёт для автоматического расчёта.</p>':''}${item('Вычет из алиментов',-off,'green')}<p class="small">Доля мамы уменьшает перевод. Отдельный приход денег не начисляется.</p></div><div class="gray"><div class="row"><h3>Дополнительные расходы</h3><button class="compact" onclick="addItem('extra')">＋</button></div>${d.extra.filter(x=>!x.deleted).map(x=>editableItem('extra',x)).join('')}${item('Дополнительно',sum(d.extra.filter(x=>!x.deleted)))}</div><div class="gray">${item('К перечислению',CashModel.alimony(d),'green')}${item('Оплаты преподавателям в периоде',sum(CashModel.lessonPayments(d).filter(p=>CashModel.future(d,p.charge_date)&&CashModel.method(p.method)!=='cash')))}${item('Предстоящая нагрузка',child(),'green')}<p class="small">Уже проведённые списания и суммы внутри credit отдельно не вычитаются.</p></div>`}
function lessonAccountHTML(subject){const title=(subject==='hebrew'?'Иврит':'Математика')+' '+(d.lessonRecipient||d.childName||'ребёнку');return `<div class="gray"><div class="row"><h3>${esc(title)}</h3><button class="compact" onclick="editLesson('','${subject}')" aria-label="Добавить счёт: ${esc(title)}">＋</button></div><div class="small">${subject==='hebrew'?'Доля мамы: половина счёта вниз до сотни, затем минус 100 ₪. Моя доля — остаток.':'Личные расходы; суммы, передаваемые маме, входят в образование алиментов.'}</div>${d.lessonBills.filter(b=>b.subject===subject&&!b.deleted).map(b=>{const s=CashModel.lessonShares(b.total,b.shares_override),paid=sum(b.payments.filter(p=>p.paid));return `<div class="lesson-bill"><div class="row"><span>${esc(b.name)}<div class="small">${b.lessons||0} уроков${b.via_alimony?' · в переводе алиментов':''}</div></span><span class="field"><b class="money">${fmt(b.total)}</b><button class="icon" onclick="editLesson('${b.id}','${subject}')" aria-label="Изменить счёт ${esc(b.name)}">✎</button></span></div>${subject==='hebrew'?`<div class="small">(доля мамы ${fmt(s.mother)}, моя ${fmt(s.father)})${s.manual?' · подтверждено вручную':''}</div>`:''}<div class="small">Оплачено ${fmt(paid)} · осталось ${fmt(b.total-paid)}</div>${b.payments.map(p=>`<div class="lesson-payment"><span>Списание ${esc(p.charge_date)} · ${methodLabel(p.method)}<br>${p.operation_date?'Операция '+esc(p.operation_date):'Дата операции требует уточнения'}<br>${p.charge_date<=d.balanceDate?'Уже в исходном балансе':p.included_in_statement?'В общей выписке':'Отдельный платёж / прогноз'}</span><strong>${fmt(p.amount)}</strong></div>`).join('')}</div>`}).join('')||'<div class="empty">Добавьте счёт за уроки</div>'}</div>`}
function editLesson(key,subject){lessonDraft=structuredClone(d.lessonBills.find(b=>b.id===key)||{id:id(),subject,name:'Счёт за уроки',total:0,lessons:0,compensation_date:d.childDate,via_alimony:false,payments:[{id:id(),amount:0,charge_date:d.statementDate,operation_date:'',payment_date:'',method:'credit',paid:false,included_in_statement:false}]});lessonEditor()}
function lessonEditor(){const b=lessonDraft;modal(`<h3>${b.subject==='hebrew'?'Иврит':'Математика'} · счёт</h3><div class="two"><div class="form-row"><label>Название</label><input id="lessonName" value="${esc(b.name)}"></div><div class="form-row"><label>Уроков</label><input id="lessonCount" type="number" min="0" value="${b.lessons||0}"></div></div><div class="form-row"><label>Весь счёт, ₪</label><input id="lessonTotal" type="number" min="0" step=".01" value="${b.total}" oninput="previewShares()"></div><div id="lessonShares" class="small"></div>${b.subject==='hebrew'?`<div class="form-row"><label>Дата однократного вычета</label><input id="lessonOffsetDate" type="date" value="${esc(b.compensation_date)}"></div><details class="help" ${b.shares_override?'open':''}><summary>Исключение для этого счёта</summary><div class="form-row"><label>Доля мамы, ₪</label><input id="motherOverride" type="number" min="0" step=".01" value="${b.shares_override?.mother??''}"></div><label><input id="confirmShares" type="checkbox" ${b.shares_override?.confirmed?'checked':''}> Подтверждаю ручные доли</label><p>Без подтверждения применяется автоматическая формула.</p></details>`:`<label class="small"><input id="lessonViaAlimony" type="checkbox" ${b.via_alimony?'checked':''}> Передаю эту сумму маме в составе образования</label>`}<h3 style="font-size:14px;margin-top:15px">Платежи</h3>${b.payments.map((p,i)=>`<div class="lesson-editor"><div class="two"><div class="form-row"><label>Сумма, ₪</label><input id="lpAmount${i}" type="number" min="0" step=".01" value="${p.amount}"></div><div class="form-row"><label>Дата банковского списания</label><input id="lpDate${i}" type="date" value="${esc(p.charge_date)}"></div><div class="form-row"><label>Дата операции</label><input id="lpOperation${i}" type="date" value="${esc(p.operation_date||'')}"></div><div class="form-row"><label>Дата оплаты</label><input id="lpPaidDate${i}" type="date" value="${esc(p.payment_date||'')}"></div></div><div class="row"><select id="lpMethod${i}">${['credit','debit','cash'].map(m=>`<option value="${m}" ${CashModel.method(p.method)===m?'selected':''}>${m==='cash'?'Наличные':m}</option>`).join('')}</select><label class="small"><input id="lpPaid${i}" type="checkbox" ${p.paid?'checked':''}> Уже оплатил</label></div><label class="small"><input id="lpIncluded${i}" type="checkbox" ${p.included_in_statement?'checked':''}> В общей выписке credit</label>${b.payments.length>1?`<button class="payment-remove" onclick="removeLessonPayment(${i})">Убрать платёж</button>`:''}</div>`).join('')}<button class="compact" onclick="addLessonPayment()">＋ Ещё платёж</button><p class="small">Сумма оплат должна совпадать со счётом. Неизвестную фактическую дату оставьте пустой.</p><div id="lessonError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveLesson()">Сохранить</button></div>`);previewShares()}
function previewShares(){const total=Number(document.getElementById('lessonTotal').value),s=CashModel.lessonShares(total);document.getElementById('lessonShares').textContent=lessonDraft.subject==='hebrew'?'Доля мамы '+fmt(s.mother)+' · моя '+fmt(s.father):'Личные расходы '+fmt(total)}
function syncLessonDraft(){Object.assign(lessonDraft,{name:document.getElementById('lessonName').value.trim()||'Счёт за уроки',total:Number(document.getElementById('lessonTotal').value),lessons:Number(document.getElementById('lessonCount').value)||0,compensation_date:document.getElementById('lessonOffsetDate')?.value||lessonDraft.compensation_date,via_alimony:document.getElementById('lessonViaAlimony')?.checked||false});const mother=document.getElementById('motherOverride'),confirmed=document.getElementById('confirmShares');lessonDraft.shares_override=confirmed?.checked?{mother:Number(mother.value),confirmed:true,at:new Date().toISOString()}:null;lessonDraft.payments.forEach((p,i)=>Object.assign(p,{amount:Number(document.getElementById('lpAmount'+i).value),charge_date:document.getElementById('lpDate'+i).value,operation_date:document.getElementById('lpOperation'+i).value,payment_date:document.getElementById('lpPaidDate'+i).value,method:document.getElementById('lpMethod'+i).value,paid:document.getElementById('lpPaid'+i).checked,included_in_statement:document.getElementById('lpIncluded'+i).checked}))}
function saveLesson(){syncLessonDraft();try{const previous=d.lessonBills.find(b=>b.id===lessonDraft.id),bills=d.lessonBills.filter(b=>b.id!==lessonDraft.id).concat(lessonDraft);validateLessons(bills);const delta=(lessonDraft.via_alimony?lessonDraft.total:0)-(previous?.via_alimony?previous.total:0);d.educationFee=Math.max(0,d.educationFee+delta);d.math=d.educationFee;d.lessonBills=bills;save('Счёт за уроки');closeModal();render()}catch(e){document.getElementById('lessonError').textContent=e.message}}
function methodLabel(value){return {credit:'credit',debit:'debit',cash:'Наличные',unconfirmed:'Не подтверждён'}[CashModel.method(value)]||value}
function removeItem(collection,key){confirmSmall('Удалить эту статью?',()=>{CashModel.removeRecord(d,{collection,id:key});save('Удаление с сохранением истории');closeModal();render()})}
function showDeleted(){modal(`<h3>Удалённые записи</h3>${d.deletedRecords.filter(x=>!x.restoredAt).map(x=>`<div class="row"><span class="small">${esc(x.record?.name||x.record?.merchant||x.ref.row_id)}<br>${esc(x.at)}</span><button class="compact" onclick="restoreDeleted('${x.id}')">Восстановить</button></div>`).join('')||'<p class="small">Нет удалённых записей.</p>'}<button class="compact" onclick="closeModal()">Закрыть</button>`)}
function restoreDeleted(key){CashModel.restoreRecord(d,key);save('Восстановление записи');closeModal();render()}
let receiptJob=0;
function registerDocument(meta){d.documents=d.documents||[];if(!d.documents.some(x=>x.id===meta.id))d.documents.push(meta)}
function receiptDraftHTML(){if(!receiptDraft)return '';const r=receiptDraft.ocr;return `<div class="gray receipt-review"><div class="row"><b>Товары в чеке</b><button class="photo-button" onclick="openDocument('${receiptDraft.document_id}')" aria-label="Оригинал чека">${uiIcon('gallery')}</button></div>${receiptDraft.error?`<div class="small red">${esc(receiptDraft.error)}</div><button class="compact" onclick="retryReceipt()">Повторить OCR</button><label class="small"><input id="receiptManualConfirmed" type="checkbox"> Проверю и введу данные вручную</label>`:`<div class="small">${esc(r.engine)} · уверенность ${Math.round(r.confidence)}%</div><div class="ocr-checks">${Object.entries(r.fields).filter(([,v])=>v.review).map(([k])=>`<label class="small"><input data-ocr-review="${k}" type="checkbox"> Проверено: ${{name:'магазин',date:'дата',amount:'итог'}[k]}</label>`).join('')}</div>${r.items.map((x,i)=>`<div class="receipt-item"><span dir="auto">${esc(x.name)}</span><span>${fmt(x.amount)} <button class="icon" onclick="editReceiptItem(${i},false)">✎</button></span></div>`).join('')}${r.adjustments.map((x,i)=>`<div class="receipt-item small"><span dir="auto">${esc(x.name)}</span><span>${fmt(x.amount)} <button class="icon" onclick="editReceiptItem(${i},true)">✎</button></span></div>`).join('')}<button class="compact" onclick="editReceiptItem(-1,false)">＋ Товар</button><div class="small">Сумма строк: ${fmt(r.items.reduce((s,x)=>s+x.amount,0)+r.adjustments.reduce((s,x)=>s+x.amount,0))}</div><label class="small"><input id="receiptItemsConfirmed" type="checkbox"> Проверены товары, скидки и расхождение с итогом</label><details class="small"><summary>Исходный распознанный текст</summary><pre dir="auto" style="white-space:pre-wrap">${esc(r.text)}</pre></details>`}</div>`}
function updateReceiptView(){document.getElementById('ocrDraftContainer').innerHTML=receiptDraftHTML()}
async function attachReceipt(file){if(!file)return;if(!/^image\/(jpeg|png|webp|gif|bmp|heic|heif)$/.test(file.type)){modal('<h3>Выберите фотографию JPEG, PNG, WebP или HEIC</h3><button onclick="closeModal()">Закрыть</button>');return}const job=++receiptJob;ocrBusy=true;document.getElementById('receiptNotice').textContent='Сохраняем оригинал и запускаем OCR на устройстве…';try{const meta=await Storage.storeDocument(file,'receipt');registerDocument(meta);const data=await DocumentEngine.recognize(file,p=>{if(job===receiptJob)document.getElementById('receiptNotice').textContent='OCR: '+p.status+' '+Math.round((p.progress||0)*100)+'%'});if(job!==receiptJob)return;const ocr=DocumentEngine.receipt(data.text,data.confidence);receiptDraft={document_id:meta.id,ocr};if(ocr.fields.name.value)document.getElementById('shop').value=ocr.fields.name.value;if(ocr.fields.date.value)document.getElementById('date').value=ocr.fields.date.value;if(ocr.fields.amount.value!==null)document.getElementById('amount').value=ocr.fields.amount.value;document.getElementById('receiptNotice').textContent='Распознано на устройстве. Проверьте отмеченные поля и товары.';updateReceiptView()}catch(e){if(job===receiptJob){receiptDraft={document_id:d.documents?.at(-1)?.id||'',error:'OCR не выполнен: '+e.message};document.getElementById('receiptNotice').textContent='Распознавание не завершено.';updateReceiptView()}}finally{if(job===receiptJob)ocrBusy=false}}
async function retryReceipt(){const doc=await Storage.getDocument(receiptDraft.document_id);if(doc){doc.blob.name=doc.name;await attachReceipt(doc.blob)}}
function editReceiptItem(index,adjustment){const x=(adjustment?receiptDraft.ocr.adjustments:receiptDraft.ocr.items)[index]||{name:'',amount:0};modal(`<h3>${adjustment?'Скидка / корректировка':'Товар'}</h3><div class="form-row"><label>Название</label><input id="receiptItemName" dir="auto" value="${esc(x.name)}"></div><div class="form-row"><label>Сумма, ₪</label><input id="receiptItemAmount" type="number" step=".01" value="${x.amount}"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button>${index>=0?`<button class="compact danger" onclick="removeReceiptItem(${index},${adjustment})">Удалить</button>`:''}<button class="compact primary" onclick="saveReceiptItem(${index},${adjustment})">Записать</button></div>`)}
function saveReceiptItem(index,adjustment){const name=document.getElementById('receiptItemName').value.trim(),amount=Number(document.getElementById('receiptItemAmount').value);if(!name||!Number.isFinite(amount))return;const xs=adjustment?receiptDraft.ocr.adjustments:receiptDraft.ocr.items;const x={...(xs[index]||{id:id()}),name,amount,review:false,corrected:true};if(index<0)xs.push(x);else xs[index]=x;closeModal();updateReceiptView()}
function removeReceiptItem(index,adjustment){(adjustment?receiptDraft.ocr.adjustments:receiptDraft.ocr.items).splice(index,1);closeModal();updateReceiptView()}
function addPurchase(){if(ocrBusy){modal('<h3>Дождитесь окончания OCR</h3><button class="compact" onclick="closeModal()">Закрыть</button>');return}const name=document.getElementById('shop').value.trim(),amount=Number(document.getElementById('amount').value),date=document.getElementById('date').value,category=document.getElementById('customCategory').value.trim()||document.getElementById('category').value,status=document.getElementById('status').value;if(!name||!Number.isFinite(amount)||amount<=0||!CashModel.validDate(date)||!category){modal('<h3>Заполните название, сумму, дату и категорию</h3><button class="compact" onclick="closeModal()">Закрыть</button>');return}if(receiptDraft){if(receiptDraft.error&&!document.getElementById('receiptManualConfirmed')?.checked){modal('<h3>Подтвердите ручной ввод после ошибки OCR</h3><button onclick="closeModal()">Закрыть</button>');return}if(receiptDraft.ocr){const missing=[...document.querySelectorAll('[data-ocr-review]')].filter(x=>!x.checked).map(x=>x.dataset.ocrReview);if(missing.length||!document.getElementById('receiptItemsConfirmed')?.checked){modal('<h3>Проверьте поля OCR и товары</h3><p class="small">Нужно подтвердить отмеченные поля, товары и скидки.</p><button onclick="closeModal()">Закрыть</button>');return}receiptDraft.ocr.corrected={name,amount,date,items:structuredClone(receiptDraft.ocr.items),adjustments:structuredClone(receiptDraft.ocr.adjustments),confirmedAt:new Date().toISOString()}}}const x={id:id(),name,amount,date,category,method:pay,status,document_id:receiptDraft?.document_id||null,ocr:receiptDraft?.ocr?structuredClone(receiptDraft.ocr):null,receipt_items:receiptDraft?.ocr?.corrected?.items||[],source:receiptDraft?'Чек / ручная проверка':'Ручной ввод',included_in_statement:CashModel.method(pay)==='credit'&&['Включено в выписку','Списано со счёта'].includes(status),charge_date:CashModel.chargeDate({date,method:pay},d),charge_estimated:CashModel.method(pay)==='credit'};if(status==='Запланировано')d.planned.push(x);else d.purchases.push(x);receiptDraft=null;draftAttachment=null;save('Новая покупка');render();const stats=CashModel.calculate(d),target=CashModel.saving(d);modal(`<h3>Покупка сохранена</h3>${item('Лимит новых покупок',stats.free+purchasesCash()+purchasesCard())}${item('Потрачено',purchasesCash()+purchasesCard())}${item('Осталось до цели',stats.free)}${item('Прогноз до '+prettyDate(d.periodEnd),stats.forecast)}${item('Отклонение от цели расходов',target.excess,target.excess?'red':'green')}<button class="compact primary" onclick="closeModal()">Готово</button>`)}
function viewReceipt(key){const x=d.purchases.find(x=>x.id===key);if(x?.document_id)openDocument(x.document_id);else if(x?.attachment&&/^data:image\/(png|jpeg|webp|gif);base64,/.test(x.attachment))modal('<img class="attachment" src="'+esc(x.attachment)+'" alt="Оригинал чека"><button onclick="closeModal()">Закрыть</button>')}
async function openDocument(key){const doc=await Storage.getDocument(key);if(!doc){modal('<h3>Оригинал не найден</h3><p class="small">Восстановите полную ZIP-копию с документами.</p><button onclick="closeModal()">Закрыть</button>');return}const url=URL.createObjectURL(doc.blob),kind=/pdf/i.test(doc.mime+doc.name)?'pdf':/csv|xlsx|sheet/i.test(doc.mime+doc.name)?'excel':'image';modal(`<h3>${esc(doc.name)}</h3>${kind==='image'?`<img class="attachment" src="${url}" alt="Оригинальный документ">`:kind==='pdf'?`<iframe title="Оригинал PDF" class="pdf-original" src="${url}"></iframe>`:'<p class="small">Excel / CSV: скачайте оригинал для просмотра в табличном приложении.</p>'}<div class="actions"><a class="compact" href="${url}" download="${esc(doc.name)}">Скачать оригинал</a><button class="compact" onclick="closeModal()">Закрыть</button></div>`);setTimeout(()=>URL.revokeObjectURL(url),300000)}
async function exportData(){await Storage.flush();download('Save-Cash-data-'+TODAY()+'.json','application/json',JSON.stringify({app:'Save Cash',schemaVersion:2,dataVersion:4,exportedAt:new Date().toISOString(),documentsIncluded:false,data:d},null,2))}
async function exportBackup(){try{await Storage.flush();const bytes=await CashBackup.create(d,await Storage.documents());download('Save-Cash-full-'+TODAY()+'.zip','application/zip',bytes)}catch(e){showError('Резервная копия не создана',e)}}
function showError(title,e){modal('<h3>'+esc(title)+'</h3><p class="small">'+esc(e.message||e)+'</p><button class="compact" onclick="closeModal()">Закрыть</button>')}
async function importData(file){if(!file)return;try{let data,documents=[];if(/\.zip$/i.test(file.name)){const unpacked=await CashBackup.parse(await file.arrayBuffer());data=validData(unpacked.data);documents=unpacked.documents}else{const raw=JSON.parse(await file.text());if(raw.type==='save-cash-lesson-update'){await importLessonUpdate(raw);return}if(raw.type==='save-cash-data-patch'){await importDataPatch(raw);return}data=validData(raw)}const ids=new Set(documents.map(x=>x.id)),refs=[...data.purchases.map(x=>x.document_id),...data.bankStatements.flatMap(x=>x.document_ids||[])].filter(Boolean);for(const ref of refs)if(!ids.has(ref)&&!await Storage.getDocument(ref))throw Error('Нет документа '+ref+'. Нужна полная ZIP-копия.');confirmSmall('Восстановить данные? Текущий снимок будет сохранён.',async()=>{try{await Storage.flush();await Storage.backup('before-full-restore-'+TODAY(),d);data.initialized=true;await Storage.restore(data,documents);d=data;await Storage.migrateAttachments(d);await save('Восстановление полной копии');receiptDraft=null;closeModal();render()}catch(e){showError('Восстановление не выполнено',e)}})}catch(e){showError('Импорт не выполнен',e)}}
async function importDataPatch(raw){if(raw.app!=='Save Cash'||raw.version!==1)throw Error('Неизвестное обновление данных');const next=structuredClone(d);if(raw.lessonBills){validateLessons(raw.lessonBills);for(const b of raw.lessonBills){const i=next.lessonBills.findIndex(x=>x.id===b.id);if(i>=0)next.lessonBills[i]=b;else next.lessonBills.push(b)}}if(Number.isFinite(raw.educationFee)&&raw.educationFee>=0){next.educationFee=raw.educationFee;next.math=raw.educationFee}for(const u of raw.installmentUpdates||[]){const x=next.installments.find(x=>x.id===u.id);if(!x)continue;if(u.expected_charge_date&&CashModel.validDate(u.expected_charge_date))x.expected_charge_date=u.expected_charge_date;if(u.status)x.status=String(u.status);if(u.active!==undefined)x.active=!!u.active;if(u.included_in_statement!==undefined)x.included_in_statement=!!u.included_in_statement}if(raw.childName)next.childName=String(raw.childName);if(raw.lessonRecipient)next.lessonRecipient=String(raw.lessonRecipient);validData(next);confirmSmall('Обновить указанные счета и даты? Баланс, покупки и остальные записи сохранятся.',async()=>{await Storage.backup('before-data-patch-'+TODAY(),d);d=next;await save('Уточнение исходных счетов');closeModal();render()})}
function documentButton(ref,legacy=false){if(!ref&&!legacy)return '';if(legacy)return '<span class="small">Чек в прежней копии</span>';const meta=(d.documents||[]).find(x=>x.id===ref),name=meta?.name||'',mime=meta?.mime||'',type=/pdf/i.test(name+mime)?'PDF':/csv|xlsx|sheet/i.test(name+mime)?'Excel':'Фото';return `<button class="document-link" onclick="openDocument('${ref}')" title="Открыть оригинал">${type==='Фото'?uiIcon('gallery'):type}</button>`}
function bankReconciliationHTML(){const run=d.reconciliationRuns.find(x=>x.id===bankRunId)||d.reconciliationRuns.filter(x=>['draft','reviewed','final'].includes(x.status)).at(-1);return `<div class="row"><span class="small">Импортируйте выписку перед списанием карты. Финансы изменятся после двух подтверждений.</span><button class="compact" onclick="showReconLog()">↶ Лог</button></div><input id="bankFiles" type="file" multiple accept="image/*,.pdf,.csv,.xlsx" hidden onchange="importBankFiles(this.files)"><button class="compact primary" onclick="document.getElementById('bankFiles').click()">＋ Выписка</button><span id="bankImportProgress" class="small"></span>${d.bankStatements.length?`<div class="form-row"><label>Сохранённые выписки</label><select onchange="selectBankStatement(this.value)"><option value="">Выбрать документ</option>${d.bankStatements.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.charge_date)} · ${s.status==='full'?'полная':'частичная'}</option>`).join('')}</select></div>`:'<p class="small">Фотографии, PDF, CSV и XLSX хранятся на устройстве вместе с оригиналами. Без импортированных документов демонстрационные операции не создаются.</p>'}${run?`<div class="small">${run.full?'Полная':'Частичная'} выписка · ${esc(run.date)}${run.status==='final'?' · окончательно подтверждена':''}</div><div id="bankComparisonList">${run.decisions.map(x=>comparisonCard(run,x)).join('')}</div><div class="actions">${run.status==='final'?`<button class="compact" onclick="reopenBankRun('${run.id}')">Повторная сверка</button><button class="compact danger" onclick="rollbackBankRun('${run.id}')">Откатить сверку</button>`:`<button class="compact primary" onclick="beginBankReview('${run.id}')">Подтвердить сверку</button>`}</div>`:''}`}
function comparisonCard(run,x){const confirmed=x.manual&&x.choice,color=confirmed?'green':x.color,left=x.left,right=x.right,locked=run.status==='final';const side=(name,value,side,available)=>`<div class="compare-half ${x.choice===side?'chosen':''}"><div class="small">${name}</div><div class="compare-name" dir="auto">${esc(value?.name||'Нет записи')}</div><button class="side-amount" ${!available||locked?'disabled':''} onclick="chooseBankSide('${run.id}','${x.id}','${side}')" aria-label="Выбрать ${side==='left'?'мою':'банковскую'} сумму">${value?fmt(side==='right'?(value.amount_ils??value.amount):value.amount):'—'} ${x.choice===side?'<span class="green">✓</span>':''}</button><div class="small">${esc(side==='right'?value?.operation_date||'Дата не подтверждена':value?.date||'Дата не указана')}</div>${documentButton(value?.document_id,value?.attachment)}</div>`;return `<article class="comparison ${color}" data-decision="${x.id}"><div class="row"><b dir="auto">${esc(left?.name||right?.name||'Операция')}</b><span class="small">${confirmed?'✓ Подтверждено вручную':color==='green'?'✓ Авто':color==='yellow'?'◷ Даты':'! Требует решения'}</span></div><div class="compare-halves">${side('Моя запись',left,'left',!!left)}${side('Выписка банка',right,'right',!!right)}</div><div class="small comparison-reason">${esc(x.reason)}${right?.conflicting_imports?.length?'<br>В повторном импорте тот же ID имеет другие значения: '+right.conflicting_imports.map(v=>esc(v.name)+' · '+fmt(v.amount)+' · '+esc(v.operation_date)).join('; ')+'<br>Откройте «Банк / комиссия» и укажите подтверждённую сумму.':''}${x.fee_for?'<br>Комиссия связана с '+esc(x.fee_for):''}${x.fee_included?'<br>Комиссия уже включена в итог':''}</div>${x.choice==='exclude'?'<div class="small green">Не отдельное списание · 0,00 ₪</div>':''}${locked?`<button class="compact" onclick="undoBankDecision('${run.id}','${x.id}')">Отменить решение</button>`:`<div class="comparison-actions"><button class="compact" onclick="focusBankDecision('${run.id}','${x.id}')">Подробнее</button>${!left?`<button class="compact" onclick="associateBankRecord('${run.id}','${x.id}')">Связать с записью</button>`:''}<button class="compact" onclick="editBankDecision('${run.id}','${x.id}')">✎ Банк / комиссия</button><button class="compact" onclick="chooseBankSide('${run.id}','${x.id}','exclude')">Не отдельная операция</button></div>`}</article>`}
function refreshBankUI(){const body=document.querySelector('[data-section="bankrecon"] .section-body');if(body)body.innerHTML=bankReconciliationHTML();if(reconFocusId){const run=d.reconciliationRuns.find(x=>x.id===bankRunId),decision=run?.decisions.find(x=>x.id===reconFocusId);if(decision)modal(`<h3>Проверка операции</h3>${comparisonCard(run,decision)}<button class="compact" onclick="closeFocusedDecision()">Назад к сверке</button>`)}}
function chooseBankSide(runId,decisionId,side){try{Reconciliation.choose(d,runId,decisionId,side);bankRunId=runId;save('Выбор стороны сверки');refreshBankUI()}catch(e){showError('Выбор не применён',e)}}
function focusBankDecision(runId,key){bankRunId=runId;reconFocusId=key;refreshBankUI()}
function closeFocusedDecision(){reconFocusId=null;closeModal();refreshBankUI()}
async function importBankFiles(files){if(!files?.length)return;bankDraft={documents:[],rows:[],unparsed:[],charge_date:d.statementDate,cardId:d.cardId||'main',status:'partial'};const progress=document.getElementById('bankImportProgress');try{for(const file of files){progress.textContent=' Читаем '+file.name;const meta=await Storage.storeDocument(file,'statement');registerDocument(meta);if(d.bankStatements.some(s=>(s.document_ids||[]).includes(meta.id))){progress.textContent=' Уже импортировано: '+file.name;continue}const parsed=await DocumentEngine.readFile(file,p=>progress.textContent=' '+file.name+' · '+p.status+' '+Math.round((p.progress||0)*100)+'%');bankDraft.documents.push({...meta,text:parsed.text||'',kind:parsed.kind});bankDraft.rows.push(...parsed.rows.map(row=>({...row,document_id:meta.id})));bankDraft.unparsed.push(...parsed.unparsed.map(text=>({document_id:meta.id,text})));}if(!bankDraft.documents.length){progress.textContent=' Эти документы уже импортированы; дубликаты не созданы.';bankDraft=null;return}showBankDraft()}catch(e){showError('Импорт остановлен. Финансы не изменены',e)}}
function showBankDraft(){modal(`<h3>Проверьте выписку</h3><div class="two"><div class="form-row"><label>Дата списания с банка</label><input id="bankChargeDate" type="date" value="${esc(bankDraft.charge_date)}"></div><div class="form-row"><label>Последние 4 цифры карты</label><input id="bankCard4" inputmode="numeric" maxlength="4" value="${esc(bankDraft.cardLast4||'')}"></div></div><div class="form-row"><label>Статус документа</label><select id="bankDraftStatus"><option value="partial" ${bankDraft.status==='partial'?'selected':''}>Частичная выписка</option><option value="full" ${bankDraft.status==='full'?'selected':''}>Полная выписка</option></select></div><p class="small">Проверьте операции. Суммы в ₪; возвраты — отрицательные. Покупки и банковское списание могут иметь разные даты.</p><div class="bank-draft-rows">${bankDraft.rows.map((r,i)=>`<div class="bank-draft-row"><div class="two"><input data-bank-field="name" data-bank-index="${i}" dir="auto" value="${esc(r.name)}" aria-label="Магазин ${i+1}"><input data-bank-field="amount" data-bank-index="${i}" type="number" step=".01" value="${r.amount}" aria-label="Сумма ${i+1}"><input data-bank-field="operation_date" data-bank-index="${i}" type="date" value="${esc(r.operation_date||'')}" aria-label="Дата операции ${i+1}"><input data-bank-field="currency" data-bank-index="${i}" value="${esc(r.currency||'ILS')}" aria-label="Валюта ${i+1}"></div><div class="small">${documentButton(r.document_id)} ${r.needs_review?'Нужно проверить оригинал':'Из структурированной таблицы'}</div><label class="small"><input data-bank-checked="${i}" type="checkbox" ${r.needs_review?'':'checked'}> Строка проверена по оригиналу</label><button class="payment-remove" onclick="removeBankDraftRow(${i})">Не операция</button></div>`).join('')}</div><button class="compact" onclick="addBankDraftRow()">＋ Операция</button>${bankDraft.unparsed.length?`<details class="help"><summary>Нераспознанные строки (${bankDraft.unparsed.length})</summary>${bankDraft.unparsed.map(x=>`<div dir="auto" class="small">${esc(x.text)}</div>`).join('')}<p>Добавьте недостающие операции вручную. Частичный документ не считается окончательной выпиской.</p></details>`:''}<div id="bankDraftError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveBankDraft()">Сохранить для сверки</button></div>`)}
function syncBankDraft(){bankDraft.charge_date=document.getElementById('bankChargeDate').value;bankDraft.status=document.getElementById('bankDraftStatus').value;bankDraft.cardLast4=document.getElementById('bankCard4').value.replace(/\D/g,'').slice(-4);document.querySelectorAll('[data-bank-field]').forEach(e=>{const r=bankDraft.rows[Number(e.dataset.bankIndex)],k=e.dataset.bankField;r[k]=k==='amount'?Number(e.value):e.value});document.querySelectorAll('[data-bank-checked]').forEach(e=>bankDraft.rows[Number(e.dataset.bankChecked)].needs_review=!e.checked)}
function addBankDraftRow(){syncBankDraft();bankDraft.rows.push({id:id(),name:'',amount:0,currency:'ILS',operation_date:'',transaction_id:'',needs_review:true,document_id:bankDraft.documents[0]?.id});showBankDraft()}
function removeBankDraftRow(i){syncBankDraft();bankDraft.rows.splice(i,1);showBankDraft()}
function saveBankDraft(){syncBankDraft();try{if(!CashModel.validDate(bankDraft.charge_date)||!bankDraft.rows.length)throw Error('Укажите дату списания и добавьте операции');for(const r of bankDraft.rows)if(!r.name.trim()||!Number.isFinite(r.amount)||!CashModel.validDate(r.operation_date))throw Error('Проверьте магазин, сумму и дату каждой операции');const statement={id:id(),name:bankDraft.documents.map(x=>x.name).join(', '),hash:bankDraft.documents.map(x=>x.hash).join(':'),cardId:bankDraft.cardId,cardLast4:bankDraft.cardLast4,charge_date:bankDraft.charge_date,status:bankDraft.status,document_ids:bankDraft.documents.map(x=>x.id),sources:bankDraft.documents,unparsed:bankDraft.unparsed,rows:bankDraft.rows,importedAt:new Date().toISOString()};d.bankStatements.push(statement);bankRunId=Reconciliation.prepare(d,statement.id).id;bankDraft=null;save('Импорт банковской выписки');closeModal();render()}catch(e){document.getElementById('bankDraftError').textContent=e.message}}
function selectBankStatement(key){if(!key)return;const statement=d.bankStatements.find(x=>x.id===key),run=d.reconciliationRuns.filter(x=>x.statement_id===key&&['draft','reviewed','final'].includes(x.status)).at(-1);bankRunId=run?.id||Reconciliation.prepare(d,statement.id).id;refreshBankUI()}
function associateBankRecord(runId,decisionId){const run=d.reconciliationRuns.find(x=>x.id===runId),xs=Reconciliation.leftRecords(d,run.date,run.cardId);modal(`<h3>Выберите исходную запись</h3><div class="stack">${xs.map(x=>`<button class="compact" onclick="saveBankAssociation('${runId}','${decisionId}','${x.id}')">${esc(x.name)} · ${fmt(x.amount)} · ${esc(x.date)}</button>`).join('')||'<p class="small">Нет записей для этой карты и даты.</p>'}<button class="compact" onclick="closeModal()">Отмена</button></div>`)}
function saveBankAssociation(runId,decisionId,leftId){try{Reconciliation.associate(d,runId,decisionId,leftId);save('Ручная связь с банком');closeModal();refreshBankUI()}catch(e){showError('Связь не создана',e)}}
function editBankDecision(runId,decisionId){const run=d.reconciliationRuns.find(x=>x.id===runId),x=run.decisions.find(x=>x.id===decisionId);if(!x.right)return;const r=x.right;modal(`<h3>Банковская строка</h3><div class="form-row"><label>Название</label><input id="bankEditName" dir="auto" value="${esc(r.name)}"></div><div class="two"><div class="form-row"><label>Сумма в исходной валюте</label><input id="bankEditAmount" type="number" step=".01" value="${r.amount}"></div><div class="form-row"><label>Дата операции</label><input id="bankEditDate" type="date" value="${esc(r.operation_date)}"></div></div><div class="form-row"><label>Фактическая сумма банка в ₪ · при конвертации</label><input id="bankEditILS" type="number" step=".01" value="${r.amount_ils??''}"></div><div class="form-row"><label>Отдельная комиссия к операции</label><select id="bankFeeFor"><option value="">Не комиссия</option>${run.decisions.filter(v=>v.id!==decisionId&&v.right).map(v=>`<option value="${v.right.id}" ${x.fee_for===v.right.id?'selected':''}>${esc(v.right.name)} · ${fmt(v.right.amount)}</option>`).join('')}</select></div><label class="small"><input id="bankFeeIncluded" type="checkbox" ${x.fee_included?'checked':''}> Комиссия уже входит в банковскую сумму исходной покупки</label><p class="small">Не отмечайте включение без подтверждения документом. Отдельная комиссия сохраняется банковской строкой.</p><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="compact primary" onclick="saveBankDecision('${runId}','${decisionId}')">Сохранить</button></div>`)}
function saveBankDecision(runId,decisionId){const run=d.reconciliationRuns.find(x=>x.id===runId),x=run.decisions.find(x=>x.id===decisionId),amount=Number(document.getElementById('bankEditAmount').value),date=document.getElementById('bankEditDate').value;if(!Number.isFinite(amount)||!CashModel.validDate(date))return;x.right.name=document.getElementById('bankEditName').value.trim()||x.right.name;x.right.amount=amount;x.right.operation_date=date;const ils=document.getElementById('bankEditILS').value;if(ils!=='')x.right.amount_ils=Number(ils);else delete x.right.amount_ils;x.fee_for=document.getElementById('bankFeeFor').value||null;x.fee_included=document.getElementById('bankFeeIncluded').checked;x.choice=x.fee_included?'exclude':null;x.manual=x.fee_included;x.color='pink';x.reason=x.fee_for?'Комиссия: проверьте включение в исходный платёж':'Банковская строка исправлена · выберите сумму';run.status='draft';delete run.reviewFingerprint;save('Уточнение банка / комиссии');closeModal();refreshBankUI()}
function beginBankReview(runId){try{const review=Reconciliation.review(d,runId);save('Предварительная проверка сверки');if(!review.ok){modal(`<h3>Не решено: ${review.unresolved.length}</h3><p class="small">Выберите операцию, чтобы открыть только её сравнение.</p><div class="stack">${review.unresolved.map(x=>`<button class="compact" onclick="focusBankDecision('${runId}','${x.id}')">${esc(x.name)}</button>`).join('')}<button class="compact" onclick="closeModal()">Назад</button></div>`);return}const run=d.reconciliationRuns.find(x=>x.id===runId),next=structuredClone(d);Reconciliation.finalize(next,runId,review.fingerprint);const before=CashModel.calculate(d),after=CashModel.calculate(next);modal(`<h3>Итоговая проверка</h3><p class="small">${review.partial?'Выписка остаётся частичной. Известная часть общей суммы сохраняется с исключением покрытых строк.':'Полная выписка заменит общую сумму для этой карты и даты.'}</p>${item('Выбрано по операциям',review.total)}${item('Прогноз до сверки',before.forecast)}${item('Прогноз после сверки',after.forecast)}<p class="small">Документы и исходные записи сохранятся. Решения можно откатить через лог.</p><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="finalizeBankReview('${runId}','${review.fingerprint}')">Подтверждаю окончательно</button></div>`)}catch(e){showError('Сверка не завершена',e)}}
function finalizeBankReview(runId,token){try{const before=CashModel.calculate(d).forecast;Reconciliation.finalize(d,runId,token);const entry=d.reconciliationLog.at(-1);entry.forecast_before=before;entry.forecast_after=CashModel.calculate(d).forecast;entry.forecast_delta=entry.forecast_after-before;save('Окончательно подтверждена сверка');reconFocusId=null;closeModal();render()}catch(e){showError('Нужна повторная проверка',e)}}
function rollbackBankRun(runId){confirmSmall('Откатить всю сверку? Оригиналы и покупки сохранятся.',()=>{Reconciliation.rollback(d,runId);save('Откат сверки');closeModal();render()})}
function reopenBankRun(runId){bankRunId=Reconciliation.reopen(d,runId).id;save('Повторная сверка');refreshBankUI()}
function undoBankDecision(runId,decisionId){confirmSmall('Отменить это решение и вернуть исходную сумму?',()=>{Reconciliation.undoDecision(d,runId,decisionId);save('Отмена решения');closeModal();render()})}
function showReconLog(){modal(`<h3>История сверки</h3>${d.reconciliationLog.slice().reverse().map(x=>`<div class="purchase small"><b>${esc(x.event)}</b> · ${esc(x.at)}<br>${esc(x.operation)}<br>Моя ${x.manual_amount===null?'—':fmt(x.manual_amount)} · банк ${x.bank_amount===null?'—':fmt(x.bank_amount)} · ${esc(x.side||'')}<br>Выписка ${esc(x.statement_id)}${x.fee_for?'<br>Комиссия: '+esc(x.fee_for):''}${x.forecast_delta!==undefined?'<br>Изменение прогноза: '+fmt(x.forecast_delta):''}${x.decision_id?`<button class="compact" onclick="undoBankDecision('${x.run_id}','${x.decision_id}')">Отменить решение</button>`:''}</div>`).join('')||'<p class="small">Решений пока нет.</p>'}<button class="compact" onclick="closeModal()">Закрыть</button>`)}
function editableItem(collection,x){if(collection!=='subs')return legacyEditableItem(collection,x);return `<div class="purchase ${x.active===false?'muted':''}"><div class="row"><span>${esc(x.name)}<div class="small">${esc(x.expected_charge_date||('Ориентировочно '+(x.day||'—')+'-е'))} · ${esc(x.periodicity||'monthly')} · ${methodLabel(x.method)}</div></span><span class="field"><b class="money">${fmt(x.amount)}</b><button class="icon" onclick="editRecurring('${x.id}')">✎</button><button class="icon danger" onclick="removeItem('subs','${x.id}')">×</button></span></div><label class="small"><input type="checkbox" ${x.active!==false?'checked':''} onchange="setRecurringActive('${x.id}',this.checked)"> Учитывать</label> <label class="small"><input type="checkbox" ${x.included_in_statement?'checked':''} onchange="included('${x.id}',this.checked)"> В выписке</label></div>`}
function setRecurringActive(key,value){d.subs.find(x=>x.id===key).active=value;save('Включение / отключение абонплаты');render()}
function editRecurring(key){const x=d.subs.find(x=>x.id===key)||{id:'',name:'',amount:0,periodicity:'monthly',expected_charge_date:d.statementDate,method:'credit',included_in_statement:false,active:true};modal(`<h3>Абонплата</h3><div class="form-row"><label>Название</label><input id="recurringName" value="${esc(x.name)}"></div><div class="two"><div class="form-row"><label>Сумма, ₪</label><input id="recurringAmount" type="number" step=".01" min="0" value="${x.amount}"></div><div class="form-row"><label>Дата банковского списания</label><input id="recurringDate" type="date" value="${esc(x.expected_charge_date||d.statementDate)}"></div></div><div class="two"><select id="recurringPeriod">${[['monthly','Ежемесячно'],['weekly','Еженедельно'],['yearly','Ежегодно']].map(([v,label])=>`<option value="${v}" ${x.periodicity===v?'selected':''}>${label}</option>`).join('')}</select><select id="recurringMethod">${['credit','debit','cash'].map(v=>`<option ${CashModel.method(x.method)===v?'selected':''}>${v}</option>`).join('')}</select></div><label class="small"><input id="recurringIncluded" type="checkbox" ${x.included_in_statement?'checked':''}> В сумме credit</label><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="compact primary" onclick="saveRecurring('${key||''}')">Сохранить</button></div>`)}
function saveRecurring(key){const name=document.getElementById('recurringName').value.trim(),amount=Number(document.getElementById('recurringAmount').value),date=document.getElementById('recurringDate').value;if(!name||!Number.isFinite(amount)||amount<0||!CashModel.validDate(date))return;let x=d.subs.find(x=>x.id===key);if(!x){x={id:'sub-'+id(),active:true,source:'Ручной ввод'};d.subs.push(x)}Object.assign(x,{name,amount,expected_charge_date:date,periodicity:document.getElementById('recurringPeriod').value,method:document.getElementById('recurringMethod').value,included_in_statement:document.getElementById('recurringIncluded').checked});save('Редактирование абонплаты');closeModal();render()}
function installmentsHTML(){return `<details class="help"><summary>Зачем две отметки?</summary>«Учитывать» включает обязательство. «В выписке» исключает отдельное вычитание: оно уже в общей банковской сумме. Выключение строки не уменьшает сумму самой выписки.</details>${d.installments.filter(x=>!x.deleted).map(x=>`<div class="purchase"><div class="row"><span><b dir="auto">${esc(x.merchant)}</b><div class="small">${x.payment_index} из ${x.payment_count} · ${esc(x.expected_charge_date)}</div></span><span class="field"><b class="money">${fmt(x.amount_per_payment)}</b><button class="icon" onclick="editInstallment('${x.id}')">✎</button></span></div><div class="small">${esc(x.status)} · ${esc(x.source||'Ручной ввод')}<br>Полная сумма: ${fmt(x.full_amount??x.amount_per_payment*x.payment_count)}${x.full_amount===undefined?' · расчётная':''}<br>После этого платежа: ${Math.max(0,x.payment_count-x.payment_index)} × ${fmt(x.amount_per_payment)} = ${fmt(CashModel.remaining(x))}</div><label class="small"><input type="checkbox" ${x.included_in_statement?'checked':''} onchange="setInstallment('${x.id}','included_in_statement',this.checked)"> В сумме выписки</label> <label class="small"><input type="checkbox" ${x.active?'checked':''} onchange="setInstallment('${x.id}','active',this.checked)"> Учитывать</label><details class="small"><summary>Будущие даты</summary>${CashModel.installmentSchedule(x).filter(p=>p.date>d.balanceDate).map(p=>`<div>${p.index}/${x.payment_count} · ${esc(p.date)} · ${fmt(p.amount)}</div>`).join('')||'<div>Будущих платежей нет</div>'}</details></div>`).join('')}<button class="compact" onclick="editInstallment()">＋ Добавить рассрочку</button>`}
function editInstallment(key){const x=d.installments.find(x=>x.id===key)||{merchant:'',amount_per_payment:0,payment_index:1,payment_count:1,expected_charge_date:d.statementDate,status:'Требует сверки'};modal(`<h3>Рассрочка</h3><div class="form-row"><label>Магазин</label><input id="instMerchant" dir="auto" value="${esc(x.merchant)}"></div><div class="two"><div class="form-row"><label>Очередной платёж, ₪</label><input id="instAmount" type="number" min="0" step=".01" value="${x.amount_per_payment}"></div><div class="form-row"><label>Полная сумма, если подтверждена</label><input id="instFull" type="number" min="0" step=".01" value="${x.full_amount??''}"></div><div class="form-row"><label>Номер платежа</label><input id="instIndex" type="number" min="1" value="${x.payment_index}"></div><div class="form-row"><label>Всего платежей</label><input id="instCount" type="number" min="1" value="${x.payment_count}"></div></div><div class="form-row"><label>Дата списания текущего платежа</label><input id="instDate" type="date" value="${esc(x.expected_charge_date)}"></div><div class="form-row"><label>Статус</label><select id="instStatus"><option ${x.status==='Требует сверки'?'selected':''}>Требует сверки</option><option ${x.status==='Подтверждено'?'selected':''}>Подтверждено</option></select></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="compact primary" onclick="saveInstallment('${key||''}')">Сохранить</button></div>`)}
function saveInstallment(key){const merchant=document.getElementById('instMerchant').value.trim(),amount=Number(document.getElementById('instAmount').value),index=Number(document.getElementById('instIndex').value),count=Number(document.getElementById('instCount').value),date=document.getElementById('instDate').value,full=document.getElementById('instFull').value;if(!merchant||!Number.isFinite(amount)||amount<0||!Number.isInteger(index)||!Number.isInteger(count)||index<1||count<index||!CashModel.validDate(date))return;let x=d.installments.find(x=>x.id===key);if(!x){x={id:id(),active:true,included_in_statement:false,source:'Ручной ввод'};d.installments.push(x)}if(x.schedule)(x.schedule_history??=[]).push({at:new Date().toISOString(),schedule:structuredClone(x.schedule)});delete x.schedule;Object.assign(x,{merchant,amount_per_payment:amount,payment_index:index,payment_count:count,expected_charge_date:date,status:document.getElementById('instStatus').value});if(full!=='')x.full_amount=Number(full);else delete x.full_amount;save('Изменение рассрочки');closeModal();render()}
function cibusExtrasHTML(){return `<div class="row"><span class="small">Источник оплаты личного участия</span><select class="compact" onchange="setCibusMethod(this.value)">${[['unconfirmed','Не подтверждён'],['credit','credit'],['debit','debit'],['cash','Наличные']].map(([v,label])=>`<option value="${v}" ${d.cibusMethod===v?'selected':''}>${label}</option>`).join('')}</select></div><div class="actions"><button class="compact" onclick="autoCibusDays()">Дни по календарю</button><button class="compact" onclick="cibusTemplate()">10 рабочих + 2 выходных</button><button class="compact" onclick="addCibusActual()">＋ Фактический обед</button></div><div class="small">Выходных: ${d.cibusWeekends||0}. Не подтверждённый источник не считается банковским списанием.</div>${d.cibusActual.map(x=>`<div class="small">${esc(x.date)} · обед ${fmt(x.cost)} · моё участие ${fmt(Math.max(0,x.cost-x.employer))}</div>`).join('')}`}
function setCibusMethod(value){d.cibusMethod=value;save('Источник оплаты Cibus');render()}
function autoCibusDays(){const days=CashModel.workingDays(d.periodStart,d.periodEnd);confirmSmall('Использовать календарную оценку: '+days.work+' рабочих и '+days.weekend+' выходных?',()=>{d.cibusDays=days.work;d.cibusWeekends=days.weekend;save('Календарная оценка Cibus');render()})}
function cibusTemplate(){d.cibusDays=10;d.cibusWeekends=2;const v=CashModel.cibus(d);d.cibus50=v.n50;d.cibusOrdinary=v.ordinary;save('Шаблон дней Cibus');render()}
function addCibusActual(){modal(`<h3>Фактический обед</h3><div class="form-row"><label>Дата</label><input id="cibusFactDate" type="date" value="${TODAY()}"></div><div class="two"><div class="form-row"><label>Стоимость, ₪</label><input id="cibusFactCost" type="number" step=".01" min="0"></div><div class="form-row"><label>Участие работодателя, ₪</label><input id="cibusEmployer" type="number" step=".01" min="0" value="38"></div></div><p class="small">Этот обед заменяет один день обычного обеда в калькуляторе, а не добавляет отдельную покупку.</p><div id="cibusFactError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="compact primary" onclick="saveCibusActual()">Записать</button></div>`)}
function saveCibusActual(){const date=document.getElementById('cibusFactDate').value,cost=Number(document.getElementById('cibusFactCost').value),employer=Number(document.getElementById('cibusEmployer').value);if(!CashModel.validDate(date)||!Number.isFinite(cost)||cost<0||!Number.isFinite(employer)||employer<0)return;if(d.cibusActual.some(x=>x.date===date)){document.getElementById('cibusFactError').textContent='Обед на эту дату уже записан';return}if(d.cibusActual.length+1>d.cibusDays-d.cibus50){document.getElementById('cibusFactError').textContent='Сначала увеличьте число рабочих дней';return}d.cibusActual.push({id:id(),date,cost,employer});d.cibusOrdinary=Math.max(d.cibusOrdinary,d.cibusActual.length);save('Фактический обед Cibus');closeModal();render()}
function reconciliationHTML(){const all=CashModel.calculate(d).rows,collator=new Intl.Collator('ru',{numeric:true});let rows=all.filter(x=>!ledgerQuery||[x.name,x.source].some(s=>String(s).toLowerCase().includes(ledgerQuery.toLowerCase())));rows.sort((a,b)=>{const primary=ledgerSort.key==='amount'?a.amount-b.amount:collator.compare(String(a[ledgerSort.key]||''),String(b[ledgerSort.key]||''));return (ledgerSort.asc?1:-1)*(primary||collator.compare(a.name,b.name)||a.amount-b.amount)});return `<div class="row ledger-tools"><span class="small">Одна операция — одно списание. «В выписке» учтено общей банковской суммой.</span><button class="compact narrow" onclick="resetLedgerFilter()">Сбросить фильтр</button></div><input class="ledger-search" placeholder="Найти статью или источник" value="${esc(ledgerQuery)}" oninput="setLedgerQuery(this.value)"><table class="ledger-table"><thead><tr>${[['name','Статья'],['amount','Сумма'],['source','Источник']].map(([key,title])=>`<th><button onclick="sortLedger('${key}')">${title}${ledgerSort.key===key?(ledgerSort.asc?' ↑':' ↓'):''}</button></th>`).join('')}<th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}<div class="small">${esc(x.date)}${x.included?' · отдельно 0 ₪':''}</div></td><td>${fmt(x.amount)}</td><td>${esc(x.source)}<div class="small">${esc(x.status)}</div></td><td><button class="icon" aria-label="Изменить статью ${esc(x.name)}" onclick="editLedgerRow('${x.id}')">✎</button><button class="icon danger" aria-label="Удалить статью ${esc(x.name)}" onclick="deleteLedgerRow('${x.id}')">×</button></td></tr>`).join('')}</tbody></table><button class="compact" onclick="exportLedger()">Скачать CSV</button>`}
function sortLedger(key){ledgerSort={key,asc:ledgerSort.key===key?!ledgerSort.asc:key!=='amount'};refreshLedger()}
function setLedgerQuery(value){ledgerQuery=value;refreshLedger(true)}
function resetLedgerFilter(){ledgerQuery='';ledgerSort={key:'name',asc:true};refreshLedger()}
function refreshLedger(keepFocus=false){const target=document.querySelector('[data-section="reconciliation"] .section-body');if(target){target.innerHTML=reconciliationHTML();if(keepFocus){const input=target.querySelector('input');input.focus();input.setSelectionRange(input.value.length,input.value.length)}}}
function editLedgerRow(key){const row=CashModel.calculate(d).rows.find(x=>x.id===key),ref=row?.ref;if(!ref)return;if(ref.collection==='purchases')return editPurchase(ref.id);if(ref.collection==='subs')return editRecurring(ref.id);if(ref.collection==='installments')return editInstallment(ref.id);if(ref.collection==='lessonBills'){const bill=d.lessonBills.find(x=>x.id===ref.id);return editLesson(bill.id,bill.subject)}if(ref.collection)return editRecord(ref.collection,ref.id);if(ref.key==='balance')return editBankBalance();if(ref.key==='cibusDays'){goView('cibus');return}if(ref.key)return editMoneyKey(ref.key,row.name);showError('Редактируйте первичный источник','Откройте банковскую сверку или расчёт исходной статьи.')}
function deleteLedgerRow(key){const row=CashModel.calculate(d).rows.find(x=>x.id===key);if(!row)return;if(['statement','history'].includes(row.kind)){modal(`<h3>Банковская сумма выписки</h3><p class="small">Удаление отображаемой строки не отменяет списание банка. Для исправления измените исходную выписку и подтвердите сверку.</p><button class="compact" onclick="closeModal()">Отмена</button><button class="compact" onclick="editMoneyKey('statementTotal','Сумма выписки')">Исправить источник</button>`);return}confirmSmall('Удалить эту статью?',()=>{CashModel.removeRecord(d,row.ref?.collection?row.ref:{row_id:row.id});save('Удаление статьи из будущего расчёта');closeModal();render()})}
function reportHTML(){const groups={};for(const x of CashModel.unique(d.purchases).filter(x=>CashModel.inPeriod(d,x.date)))(groups[x.name]??=[]).push(x);return `<details class="gray" open><summary><b>По магазинам</b></summary>${Object.entries(groups).sort(([a],[b])=>a.localeCompare(b,'ru')).map(([name,xs])=>`<div class="row"><span dir="auto">${esc(name)}<div class="small">Операций: ${xs.length}</div></span><b class="money">${fmt(sum(xs))}</b></div>`).join('')||'<div class="small">Покупок пока нет.</div>'}</details>${categoryReportHTML()}`}
let graphPeriods=[];
function chartHTML(){const current={id:'current',name:'Текущий период',from:d.periodStart,to:d.periodEnd,total:CashModel.calculate(d).rows.filter(x=>CashModel.method(x.method)==='credit'&&!x.included&&x.kind!=='history').reduce((s,x)=>s+x.amount,0),entries:CashModel.unique(d.purchases).filter(x=>CashModel.method(x.method)==='credit'&&CashModel.inPeriod(d,x.date)),forecast:true};const all=[...d.history,...d.periodArchive.map(x=>({...x,name:x.from+'–'+x.to,entries:x.purchases})),current],ids=d.selectedPeriods.length?d.selectedPeriods:[...all.slice(-2).map(x=>x.id)];graphPeriods=all.filter(x=>ids.includes(x.id));const colors=['#19835c','#4c78a8','#bc7b36','#935f9c'],max=Math.max(1,...graphPeriods.map(x=>Number(x.total)||0));const xPos=day=>35+day/32*285,yPos=value=>145-value/max*118;const plots=graphPeriods.map((period,i)=>{const rows=(period.entries||[]).filter(x=>!CashModel.excluded(x)).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));let cumulative=0;period.points=[];for(const x of rows){const start=period.from||d.periodStart,day=Math.max(0,(Date.parse(x.date)-Date.parse(start))/86400000);cumulative+=x.amount;period.points.push({day,value:cumulative,date:x.date})}const known=period.points.length?`<polyline points="${[[35,145],...period.points.map(p=>[xPos(p.day),yPos(p.value)])].map(x=>x.join(',')).join(' ')}" stroke="${colors[i%4]}" fill="none" stroke-width="2"/>`:'';const last=period.points.at(-1),end=32;return `${known}${period.forecast&&last?`<path d="M${xPos(last.day)} ${yPos(last.value)}L${xPos(end)} ${yPos(period.total)}" stroke="${colors[i%4]}" stroke-dasharray="4 4" fill="none"/>`:''}<circle cx="${xPos(end)}" cy="${yPos(period.total)}" r="4" fill="${colors[i%4]}"/>`}).join('');const saving=CashModel.saving(d);return `<div class="small">Бюджетный навигатор — Антон. Дневные линии строятся только по сохранённым операциям. Если известен лишь итог периода, показана точка; пунктир — прогноз.</div><div class="actions">${all.map(x=>`<button class="compact ${ids.includes(x.id)?'primary':''}" onclick="togglePeriod('${x.id}')">${esc(x.name)}</button>`).join('')}</div><svg id="budgetPlot" viewBox="0 0 350 180" role="img" aria-label="Сравнение периодов бюджета" style="touch-action:none" onpointerdown="this.setPointerCapture(event.pointerId);chartHover(event)" onpointermove="if(event.buttons)chartHover(event)"><path d="M35 15V145H325" stroke="#bbb" fill="none"/>${plots}<path id="plotCursor" d="M35 15V145" stroke="#aaa" stroke-dasharray="3 3"/><text x="35" y="167" font-size="10">15-е · начало</text><text x="260" y="167" font-size="10">15-е · конец</text></svg><div id="graphReadout" class="small">Проведите по графику для просмотра известных сумм.</div>${graphPeriods.length===2?item('Разница выбранных итогов',Number(graphPeriods[1].total)-Number(graphPeriods[0].total)):'<div class="small">Выберите два периода для сравнения.</div>'}<div class="gray">${editable('previousSpending','Расходы сравнительного периода')}${editable('savingGoal','Цель сокращения трат')}${editable('comparedSpending','Сценарий расходов')}${item('Предел расходов',saving.ceiling)}${item('Превышение',saving.excess,'red')}${item('Экономия следующего периода',saving.nextGoal)}<button class="compact" onclick="carryExcess()">Перенести превышение</button></div>`}
function chartHover(event){const svg=document.getElementById('budgetPlot'),bounds=svg.getBoundingClientRect(),x=Math.max(35,Math.min(320,(event.clientX-bounds.left)/bounds.width*350)),day=(x-35)/285*32;document.getElementById('plotCursor').setAttribute('d','M'+x+' 15V145');document.getElementById('graphReadout').textContent=graphPeriods.map(p=>{const point=p.points?.filter(x=>x.day<=day).at(-1);return p.name+': '+(point?fmt(point.value)+' на '+point.date:day>=31?fmt(p.total)+' · итог':'нет дневных данных')}).join(' · ')}
function openNextPeriod(){confirmSmall('Открыть следующий период? Сохраним историю; затем обновите баланс банка.',async()=>{try{await Storage.backup('before-period-'+d.periodEnd,d);CashModel.archivePeriod(d);const oldEnd=d.periodEnd;d.periodStart=new Date(Date.parse(oldEnd+'T12:00:00Z')+86400000).toISOString().slice(0,10);d.periodEnd=CashModel.addMonths(oldEnd,1);d.carry=Number(d.nextPeriodCarry||0);d.nextPeriodCarry=0;d.statementTotal=0;d.statementStatus='Частичная выписка';d.statementDate=d.periodEnd;d.salaryDate=d.periodEnd.slice(0,8)+'07';d.rentDate=d.periodEnd;d.childDate=d.periodEnd.slice(0,8)+'01';d.loanActive=false;d.cibusIncluded=false;d.cibusActual=[];for(const x of d.subs){x.included_in_statement=false;const step=x.periodicity==='yearly'?12:1;let date=x.expected_charge_date||oldEnd;while(date<d.periodStart)date=x.periodicity==='weekly'?new Date(Date.parse(date+'T12:00:00Z')+7*86400000).toISOString().slice(0,10):CashModel.addMonths(date,step);x.expected_charge_date=date}for(const x of d.installments){const schedule=CashModel.installmentSchedule(x);x.schedule=schedule;x.included_in_statement=false;if(schedule.length&&schedule.at(-1).date<d.periodStart){x.active=false;x.schedule_finished_at=d.periodStart}}await save('Открытие следующего периода');closeModal();render()}catch(e){showError('Период не изменён',e)}})}
function showPeriodSettings(){modal(`<h3>Расчётный период и даты</h3><p class="small">Личный credit: 15-е → 15-е. Семейный бюджет ведётся отдельно: 10-е → 9-е. Личные и семейные суммы автоматически не смешиваются.</p><button class="compact" onclick="openNextPeriod()">Открыть следующий период</button>${dateField('periodStart','Начало')}${dateField('periodEnd','Конец')}${dateField('salaryDate','Зарплата')}${dateField('childDate','Алименты')}<p class="small">Текущий баланс и его дату меняйте карандашом в верхней карточке. Кредит не переносится автоматически.</p><button class="compact" onclick="closeModal()">Закрыть</button>`)}
let pendingPurchaseEditor=null;
function editPurchase(key){legacyEditPurchase(key);const x=d.purchases.find(x=>x.id===key),modalBody=document.querySelector('.modal');if(x.document_id)modalBody.insertAdjacentHTML('beforeend',`<div class="line"></div>${documentButton(x.document_id)}<span class="small"> Оригинальный чек</span>`);if(x.receipt_items?.length)modalBody.insertAdjacentHTML('beforeend',`<details class="help" open><summary>Товары в чеке (${x.receipt_items.length})</summary>${x.receipt_items.map((v,i)=>`<div class="receipt-item"><span dir="auto">${esc(v.name)}</span><span>${fmt(v.amount)} <button class="icon" onclick="editSavedReceiptItem('${key}',${i})">✎</button></span></div>`).join('')}</details>`);if(x.ocr)modalBody.insertAdjacentHTML('beforeend',`<details class="help"><summary>Исходный результат OCR</summary><pre dir="auto" style="white-space:pre-wrap">${esc(x.ocr.text||x.ocr.original?.text||'')}</pre></details>`);if(pendingPurchaseEditor?.key===key)for(const [field,value]of Object.entries(pendingPurchaseEditor.fields)){const input=document.getElementById(field);if(input)input.value=value}}
function savePurchase(key){const x=d.purchases.find(x=>x.id===key);if(x.ocr)x.ocr.corrected={...(x.ocr.corrected||{}),name:document.getElementById('editName').value.trim(),amount:Number(document.getElementById('editAmount').value),date:document.getElementById('editDate').value,items:structuredClone(x.receipt_items||[]),confirmedAt:new Date().toISOString()};pendingPurchaseEditor=null;legacySavePurchase(key)}
function editSavedReceiptItem(key,index){const x=d.purchases.find(x=>x.id===key),item=x.receipt_items[index];pendingPurchaseEditor={key,fields:Object.fromEntries(['editName','editAmount','editDate','editCharge','editStatus','editLink'].map(field=>[field,document.getElementById(field)?.value||'']))};modal(`<h3>Товар из сохранённого чека</h3><div class="form-row"><label>Название</label><input id="savedItemName" dir="auto" value="${esc(item.name)}"></div><div class="form-row"><label>Сумма, ₪</label><input id="savedItemAmount" type="number" step=".01" value="${item.amount}"></div><p class="small">Изменение товара не создаёт отдельное банковское списание. Итог покупки редактируется отдельно.</p><div class="actions"><button class="compact" onclick="editPurchase('${key}')">Отмена</button><button class="compact primary" onclick="saveSavedReceiptItem('${key}',${index})">Сохранить товар</button></div>`)}
function saveSavedReceiptItem(key,index){const x=d.purchases.find(x=>x.id===key),name=document.getElementById('savedItemName').value.trim(),amount=Number(document.getElementById('savedItemAmount').value);if(!name||!Number.isFinite(amount))return;Object.assign(x.receipt_items[index],{name,amount,corrected:true});if(x.ocr)x.ocr.corrected={...(x.ocr.corrected||{}),items:structuredClone(x.receipt_items),confirmedAt:new Date().toISOString()};save('Исправление товара в чеке');editPurchase(key)}
function editable(key,label){if(key==='balance')return `<div class="row"><span>${label}</span><span class="field"><b class="money">${fmt(d.balance)}</b><button class="icon" onclick="editBankBalance()" aria-label="Изменить баланс банка">✎</button></span></div>`;return legacyEditable(key,label)}

if("serviceWorker" in navigator){window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").then(r=>swRegistration=r).catch(e=>{const n=document.getElementById("storage-state");if(n)n.textContent="Офлайн-режим недоступен: "+e.message}))}
start();
